__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"LEVEL_DATA",{enumerable:!0,get:function(){return u}});var t=r(d[0]),n=r(d[1]),_=r(d[2]),o=r(d[3]);const u={words:(0,r(d[4]).withExamples)(o.N3_WORDS,_.N3_EXAMPLES),grammar:t.N3_GRAMMAR,reading:n.N3_READING}},1245,[1246,1247,1248,1249,1235]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"N3_GRAMMAR",{enumerable:!0,get:function(){return n}});const n=[{id:'n3-g01',pattern:'〜わけだ',connection:'普通形 ＋ わけだ',meaning:'難怪〜；也就是說〜',example:{ja:'十年住んでいたのか。日本語が上手なわけだ。',zh:'住了十年啊，難怪日文這麼好。',highlight:'上手なわけだ'},tip:'表示根據事實推出「難怪、當然」的結論；與「はずだ」（說話前的推測）區分，わけだ多用於恍然大悟。',quiz:{blank:'わけだ',distractors:['わけがない','わけではない','ところだ']}},{id:'n3-g02',pattern:'〜はずだ',connection:'普通形 ＋ はずだ',meaning:'應該〜（推測）',example:{ja:'彼は今日休みだから、家にいるはずだ。',zh:'他今天休假，應該在家。',highlight:'いるはずだ'},tip:'表示有根據的推測；否定「はずがない」＝不可能。勿與表達結論的「わけだ」混淆。',quiz:{blank:'はずだ',distractors:['はずがない','わけがない','ことはない']}},{id:'n3-g03',pattern:'〜ようとする',connection:'動詞意向形 ＋ とする',meaning:'正想要〜',example:{ja:'出かけようとしたとき、電話が鳴った。',zh:'正要出門的時候，電話響了。',highlight:'出かけようとした'},tip:'意向形＋とする＝正要做某事的瞬間；「ようにする」是努力做到，兩者常被混用。',quiz:{blank:'ようとした',distractors:['ようにした','ることにした','させた']}},{id:'n3-g04',pattern:'〜うちに',connection:'動詞辭書形／ない形 ＋ うちに',meaning:'趁〜的時候',example:{ja:'忘れないうちに、メモしておこう。',zh:'趁還沒忘記先記下來吧。',highlight:'忘れないうちに'},tip:'「〜ないうちに」＝趁還沒〜；常與「〜前に」比較，前に只接辭書形。',quiz:{blank:'ないうちに',distractors:['たうちに','ないまえに','るうちに']}},{id:'n3-g05',pattern:'〜たとたん',connection:'動詞た形 ＋ とたん',meaning:'一〜就（馬上）',example:{ja:'警察が来たとたん、犯人は逃げ出した。',zh:'警察一來，犯人就逃走了。',highlight:'来たとたん'},tip:'只接た形，後句為說話者無法控制的意外事態，不能接意志、命令句。',quiz:{blank:'たとたん',distractors:['るとたん','たうちに','たまま']}},{id:'n3-g06',pattern:'〜くせに',connection:'普通形 ＋ くせに',meaning:'明明〜卻（帶責備）',example:{ja:'知っているくせに、何も言わない。',zh:'明明知道卻什麼也不說。',highlight:'知っているくせに'},tip:'帶強烈責備或不滿，前後主語須相同；「のに」較中性，くせに語氣更負面。',quiz:{blank:'くせに',distractors:['おかげで','ように','ついでに']}},{id:'n3-g07',pattern:'〜ばかり',connection:'動詞て形 ＋ ばかりいる',meaning:'老是〜',example:{ja:'弟はゲームをしてばかりいる。',zh:'弟弟老是在玩遊戲。',highlight:'してばかりいる'},tip:'「てばかりいる」表示老是做同一件事（帶不滿）；名詞＋ばかり則是「淨是〜」。',quiz:{blank:'ばかり',distractors:['だけ','しか','ほど']}},{id:'n3-g08',pattern:'〜によって',connection:'名詞 ＋ によって',meaning:'依〜而（不同）；由於〜',example:{ja:'国によって習慣が違う。',zh:'習慣因國家而異。',highlight:'国によって'},tip:'「依〜而不同」後句常接「違う・異なる」；也可表原因、手段、被動句動作者。',quiz:{blank:'によって',distractors:['にとって','について','に対して']}},{id:'n3-g09',pattern:'〜に対して',connection:'名詞 ＋ に対して',meaning:'對於〜',example:{ja:'先生の質問に対して、はっきり答えた。',zh:'對老師的問題清楚地回答了。',highlight:'質問に対して'},tip:'表示動作對象或對比；「にとって」是「對〜而言」（評價立場），兩者常被混淆。',quiz:{blank:'に対して',distractors:['にとって','によって','として']}},{id:'n3-g10',pattern:'〜として',connection:'名詞 ＋ として',meaning:'作為〜',example:{ja:'彼は探偵として有名だ。',zh:'他作為偵探很有名。',highlight:'探偵として'},tip:'表示身分、資格、立場；「にとって」表評價者立場，考題常二選一。',quiz:{blank:'として',distractors:['にとって','について','によって']}},{id:'n3-g11',pattern:'〜おかげで',connection:'普通形／名詞の ＋ おかげで',meaning:'多虧〜',example:{ja:'先生のおかげで、合格できました。',zh:'多虧老師，我考上了。',highlight:'おかげで'},tip:'用於好的結果、帶感謝；壞結果用「せいで」，兩者是固定對比考點。',quiz:{blank:'おかげで',distractors:['せいで','くせに','ついでに']}},{id:'n3-g12',pattern:'〜せいで',connection:'普通形／名詞の ＋ せいで',meaning:'都怪〜',example:{ja:'雨のせいで、試合が中止になった。',zh:'都怪下雨，比賽取消了。',highlight:'せいで'},tip:'用於壞結果、帶歸咎語氣；好結果用「おかげで」。',quiz:{blank:'せいで',distractors:['おかげで','くせに','たびに']}},{id:'n3-g13',pattern:'〜ことにしている',connection:'動詞辭書形／ない形 ＋ ことにしている',meaning:'（習慣上）一向〜',example:{ja:'夜十時以降は何も食べないことにしている。',zh:'我規定自己晚上十點以後不吃東西。',highlight:'食べないことにしている'},tip:'「ことにしている」是自己決定的習慣；「ことになっている」是外部規定，常考對比。',quiz:{blank:'ことにしている',distractors:['ことになっている','ことがある','ことはない']}},{id:'n3-g14',pattern:'〜っぽい',connection:'名詞／動詞ます形／形容詞語幹 ＋ っぽい',meaning:'有〜的感覺；容易〜',example:{ja:'彼は大人なのに、考え方が子どもっぽい。',zh:'他明明是大人，想法卻很孩子氣。',highlight:'子どもっぽい'},tip:'帶「有點〜、容易〜」的負面語感；「らしい」則表示具備該身分應有的典型特質。',quiz:{blank:'っぽい',distractors:['がち','げ','ぎみ']}},{id:'n3-g15',pattern:'〜ついでに',connection:'動詞辭書形／た形／名詞の ＋ ついでに',meaning:'順便〜',example:{ja:'コンビニへ行くついでに、手紙を出してきて。',zh:'去便利商店時順便幫我寄信。',highlight:'行くついでに'},tip:'藉做A的機會順便做B，A是主要目的；前接名詞須加「の」。',quiz:{blank:'ついでに',distractors:['たびに','うちに','とおりに']}},{id:'n3-g16',pattern:'〜たびに',connection:'動詞辭書形／名詞の ＋ たびに',meaning:'每次〜都〜',example:{ja:'この歌を聞くたびに、故郷を思い出す。',zh:'每次聽到這首歌就會想起故鄉。',highlight:'聞くたびに'},tip:'「每次〜就一定〜」，前接辭書形或名詞＋の；後句不用意志表現。',quiz:{blank:'たびに',distractors:['ついでに','とたん','うちに']}},{id:'n3-g17',pattern:'〜とおりに',connection:'動詞辭書形／た形／名詞の ＋ とおりに',meaning:'按照〜',example:{ja:'説明書に書いてあるとおりに組み立ててください。',zh:'請按照說明書上寫的組裝。',highlight:'書いてあるとおりに'},tip:'按照前項所說、所寫去做；名詞可直接接「どおり」（例：予定どおり）。',quiz:{blank:'とおりに',distractors:['たびに','ついでに','ばかりに']}},{id:'n3-g18',pattern:'〜最中に',connection:'動詞ている形／名詞の ＋ 最中に',meaning:'正在〜的時候',example:{ja:'会議の最中に、携帯電話が鳴った。',zh:'開會開到一半，手機響了。',highlight:'会議の最中に'},tip:'強調動作正在進行的高峰期被打斷，後句多為突發事件；接「ている形」或名詞の。',quiz:{blank:'最中に',distractors:['ついでに','とたんに','たびに']}},{id:'n3-g19',pattern:'〜にとって',connection:'名詞 ＋ にとって',meaning:'對〜來說',example:{ja:'私にとって、家族が一番大切です。',zh:'對我來說，家人最重要。',highlight:'私にとって'},tip:'後接評價語（大切・難しい等）；不可接表態度的動作，那是「に対して」。',quiz:{blank:'にとって',distractors:['によって','に対して','について']}},{id:'n3-g20',pattern:'〜について',connection:'名詞 ＋ について',meaning:'關於〜',example:{ja:'日本の歴史についてレポートを書きました。',zh:'寫了一篇關於日本歷史的報告。',highlight:'日本の歴史について'},tip:'「關於〜」後接說、寫、想、調查等動詞；修飾名詞時用「についての」。',quiz:{blank:'について',distractors:['にとって','として','に対して']}},{id:'n3-g21',pattern:'〜によると',connection:'名詞 ＋ によると',meaning:'根據〜（消息來源）',example:{ja:'ニュースによると、台風が近づいているそうだ。',zh:'根據新聞，颱風正在接近。',highlight:'ニュースによると'},tip:'表示消息來源，句尾常與「そうだ・らしい」呼應。',quiz:{blank:'によると',distractors:['について','にとって','に対して']}},{id:'n3-g22',pattern:'〜わけではない',connection:'普通形 ＋ わけではない',meaning:'並不是〜',example:{ja:'嫌いなわけではないが、あまり食べない。',zh:'並不是討厭，只是不常吃。',highlight:'嫌いなわけではない'},tip:'部分否定「並非全然〜」；與全面否定的「わけがない」（不可能）要區分。',quiz:{blank:'わけではない',distractors:['わけがない','わけだ','はずがない']}},{id:'n3-g23',pattern:'〜わけがない',connection:'普通形 ＋ わけがない',meaning:'不可能〜；絕不會〜',example:{ja:'あんなにまじめな人が嘘をつくわけがない。',zh:'那麼認真的人不可能說謊。',highlight:'嘘をつくわけがない'},tip:'說話者強烈主觀否定「絕不可能」；近義「はずがない」，但「わけではない」是部分否定。',quiz:{blank:'わけがない',distractors:['わけではない','わけだ','ことがある']}},{id:'n3-g24',pattern:'〜ことはない',connection:'動詞辭書形 ＋ ことはない',meaning:'不必〜；用不著〜',example:{ja:'簡単な試験だから、心配することはないよ。',zh:'考試很簡單，不必擔心啦。',highlight:'心配することはない'},tip:'「不必〜」用於勸慰、建議；勿與經驗「たことがない」混淆。',quiz:{blank:'ことはない',distractors:['ことがある','ことにする','わけだ']}},{id:'n3-g25',pattern:'〜だけでなく',connection:'普通形／名詞 ＋ だけでなく',meaning:'不只〜還〜',example:{ja:'この店は味だけでなく、サービスもいい。',zh:'這家店不只味道好，服務也很好。',highlight:'味だけでなく'},tip:'不只A還有B，後句常用「も」呼應；近義「ばかりでなく」較書面。',quiz:{blank:'だけでなく',distractors:['かわりに','によって','にとって']}},{id:'n3-g26',pattern:'〜にしては',connection:'普通形／名詞 ＋ にしては',meaning:'以〜來說（意外地）',example:{ja:'十歳にしては、ずいぶんしっかりしている。',zh:'以十歲來說，相當穩重。',highlight:'十歳にしては'},tip:'實際情況與從前項推想的標準不符；「わりに」相近，但にしては多接名詞或具體事實。',quiz:{blank:'にしては',distractors:['にとって','として','について']}},{id:'n3-g27',pattern:'〜ほど',connection:'動詞辭書形／ない形／い形容詞／名詞 ＋ ほど',meaning:'〜到幾乎〜的程度',example:{ja:'泣きたいほど足が痛かった。',zh:'腳痛到想哭。',highlight:'泣きたいほど'},tip:'表示程度到某種地步；與「くらい」可互換，但「ば〜ほど」是「越〜越〜」。',quiz:{blank:'ほど',distractors:['ばかり','だけ','まで']}},{id:'n3-g28',pattern:'〜ば〜ほど',connection:'動詞ば形 ＋ 同動詞辭書形 ＋ ほど',meaning:'越〜越〜',example:{ja:'日本語は勉強すればするほど面白くなる。',zh:'日文越學越有趣。',highlight:'すればするほど'},tip:'前後同一個詞重複，ば形＋辭書形＋ほど；な形容詞為「〜なら〜なほど」。',quiz:{blank:'ほど',distractors:['まで','ばかり','うちに']}},{id:'n3-g29',pattern:'〜からといって',connection:'普通形 ＋ からといって',meaning:'雖說〜但也不見得〜',example:{ja:'高いからといって、品質がいいとは限らない。',zh:'雖說價格貴，品質也不一定好。',highlight:'高いからといって'},tip:'後句常與「とは限らない・わけではない」呼應，表示不能僅憑前項就下結論。',quiz:{blank:'からといって',distractors:['からこそ','ばかりに','おかげで']}},{id:'n3-g30',pattern:'〜かわりに',connection:'動詞普通形／名詞の ＋ かわりに',meaning:'代替〜；作為交換〜',example:{ja:'父のかわりに、私が会議に出席した。',zh:'我代替父親出席了會議。',highlight:'父のかわりに'},tip:'有「代替」與「交換」兩義；名詞＋にかわって只有「代替」義。',quiz:{blank:'かわりに',distractors:['おかげで','せいで','たびに']}},{id:'n3-g31',pattern:'〜ても構わない',connection:'動詞て形 ＋ も構わない',meaning:'〜也沒關係',example:{ja:'このペンは使っても構いません。',zh:'這支筆你用也沒關係。',highlight:'使っても構いません'},tip:'表示允許、讓步，比「てもいい」略正式；否定「てはいけない」是禁止。',quiz:{blank:'も構いません',distractors:['はいけません','はなりません','も仕方がありません']}},{id:'n3-g32',pattern:'〜っけ',connection:'普通形（た形） ＋ っけ',meaning:'是不是〜來著？（確認回想）',example:{ja:'会議は何時からだったっけ。',zh:'會議是幾點開始來著？',highlight:'だったっけ'},tip:'口語中確認自己記不清的事；常接過去式「だったっけ」，不用於正式場合。',quiz:{blank:'っけ',distractors:['ものか','ことだ','ところだ']}},{id:'n3-g33',pattern:'〜としたら',connection:'普通形 ＋ としたら',meaning:'假如〜的話',example:{ja:'もし宝くじが当たったとしたら、何をしたい？',zh:'假如中了樂透，你想做什麼？',highlight:'当たったとしたら'},tip:'假設條件，後句多為說話者的判斷或疑問；「としても」是「即使〜也」。',quiz:{blank:'としたら',distractors:['としても','ところで','とたん']}},{id:'n3-g34',pattern:'〜みたいだ',connection:'普通形（な形・名詞去だ） ＋ みたいだ',meaning:'好像〜（口語）',example:{ja:'外がうるさいね。お祭りみたいだ。',zh:'外面好吵，好像在辦祭典。',highlight:'お祭りみたいだ'},tip:'「ようだ」的口語；名詞、な形容詞直接接みたい，不加「の」或「な」。',quiz:{blank:'みたいだ',distractors:['ようだ','そうだ','がちだ']}},{id:'n3-g35',pattern:'〜おきに',connection:'數量詞 ＋ おきに',meaning:'每隔〜',example:{ja:'このバスは十五分おきに来ます。',zh:'這班公車每隔十五分鐘來一班。',highlight:'十五分おきに'},tip:'「每隔〜」接數量詞；「一日おき」＝隔一天（隔日），與「一日ごと」（每天）意思不同，常考。',quiz:{blank:'おきに',distractors:['たびに','ぶりに','までに']}},{id:'n3-g36',pattern:'〜に比べて',connection:'名詞 ＋ に比べて',meaning:'與〜相比',example:{ja:'去年に比べて、今年は雨が多い。',zh:'和去年相比，今年雨比較多。',highlight:'去年に比べて'},tip:'比較兩者差異，後句常為「多い・高い」等比較；勿與表對比對象的「に対して」混淆。',quiz:{blank:'に比べて',distractors:['にとって','によって','について']}},{id:'n3-g37',pattern:'〜につれて',connection:'動詞辭書形／名詞 ＋ につれて',meaning:'隨著〜',example:{ja:'年をとるにつれて、体力が落ちてきた。',zh:'隨著年紀增長，體力變差了。',highlight:'年をとるにつれて'},tip:'前後都是逐漸變化的事物；後句不可接意志表現，近義「に従って」。',quiz:{blank:'につれて',distractors:['にとって','において','に対して']}},{id:'n3-g38',pattern:'〜まま',connection:'動詞た形／ない形／名詞の ＋ まま',meaning:'保持〜的狀態',example:{ja:'電気をつけたまま寝てしまった。',zh:'開著燈就睡著了。',highlight:'つけたまま'},tip:'維持前項狀態去做後項（常為不自然狀態）；否定「ないまま」，名詞須加「の」。',quiz:{blank:'たまま',distractors:['ないまま','ながら','るうちに']}},{id:'n3-g39',pattern:'〜ことになっている',connection:'動詞辭書形／ない形 ＋ ことになっている',meaning:'規定〜；預定〜',example:{ja:'この寮では、夜十一時以降は外出できないことになっている。',zh:'這間宿舍規定晚上十一點以後不能外出。',highlight:'できないことになっている'},tip:'表示外部規定或約定；自己定的習慣用「ことにしている」，常考對比。',quiz:{blank:'ことになっている',distractors:['ことにしている','ことがある','ことはない']}},{id:'n3-g40',pattern:'〜に関して',connection:'名詞 ＋ に関して',meaning:'關於〜（較正式）',example:{ja:'この件に関して、ご質問はありますか。',zh:'關於這件事，有什麼問題嗎？',highlight:'この件に関して'},tip:'「について」的正式說法；修飾名詞用「に関する」或「に関しての」。',quiz:{blank:'に関して',distractors:['にとって','によって','につれて']}},{id:'n3-g41',pattern:'〜ように（如同）',connection:'動詞普通形／名詞の ＋ ように',meaning:'如同〜；正如〜',example:{ja:'先ほど説明したように、犯人は左利きです。',zh:'正如剛才說明的，犯人是左撇子。',highlight:'説明したように'},tip:'「正如〜所說」，前接說明、說、預報等；句中修飾動詞或句子，不接名詞。',quiz:{blank:'ように',distractors:['ような','ために','ばかりに']}},{id:'n3-g42',pattern:'〜ような（舉例）',connection:'名詞 ＋ の ＋ ような',meaning:'像〜這樣的',example:{ja:'探偵のような仕事がしてみたい。',zh:'我想試試看像偵探這樣的工作。',highlight:'探偵のような'},tip:'舉例或比喻「像〜這樣的」後接名詞；接動詞、形容詞時要用「ように」。',quiz:{blank:'ような',distractors:['ように','ようだ','みたいな']}},{id:'n3-g43',pattern:'〜ようだ（比喻）',connection:'普通形／名詞の ＋ ようだ',meaning:'好像〜一樣（比喻）',example:{ja:'彼の推理はまるで魔法のようだ。',zh:'他的推理簡直像魔法一樣。',highlight:'魔法のようだ'},tip:'比喻常與「まるで」呼應；名詞＋の＋ようだ，「みたいだ」則不加の。',quiz:{blank:'ようだ',distractors:['みたいだ','そうだ','らしい']}},{id:'n3-g44',pattern:'〜みたいに（比喻）',connection:'普通形／名詞 ＋ みたいに',meaning:'像〜一樣地',example:{ja:'彼は子どもみたいにはしゃいでいる。',zh:'他像小孩子一樣興奮地嬉鬧。',highlight:'子どもみたいに'},tip:'「ように」的口語版，修飾動詞；名詞直接接みたいに，不加「の」。',quiz:{blank:'みたいに',distractors:['ように','みたいな','そうに']}},{id:'n3-g45',pattern:'〜ような気がする',connection:'普通形／名詞の ＋ ような気がする',meaning:'總覺得〜；好像〜',example:{ja:'この男、どこかで見たような気がする。',zh:'總覺得在哪裡見過這個男人。',highlight:'見たような気がする'},tip:'表示不確定的感覺或預感，語氣委婉；常接た形表示「好像曾經〜」。',quiz:{blank:'ような',distractors:['ように','そうな','ようだ']}},{id:'n3-g46',pattern:'〜感じがする',connection:'普通形／名詞の ＋ 感じがする',meaning:'有〜的感覺',example:{ja:'この部屋は何か変な感じがする。',zh:'這個房間給人一種怪怪的感覺。',highlight:'変な感じがする'},tip:'表達主觀感覺，前面多用形容詞或連體修飾；助詞固定用「が」。',quiz:{blank:'感じがする',distractors:['感じをする','ことがする','ようにする']}},{id:'n3-g47',pattern:'〜ように見える',connection:'普通形／名詞の ＋ ように見える',meaning:'看起來像〜',example:{ja:'彼は落ち着いているように見えるが、本当は焦っている。',zh:'他看起來很冷靜，其實很著急。',highlight:'落ち着いているように見える'},tip:'表示從外觀判斷的樣子；與樣態「そうに見える」不同，ように接普通形。',quiz:{blank:'ように見える',distractors:['そうに見える','ようにする','ようになる']}},{id:'n3-g48',pattern:'〜げ',connection:'い形容詞語幹／な形容詞語幹 ＋ げ',meaning:'看起來〜的樣子',example:{ja:'少女は寂しげな顔で窓の外を見ていた。',zh:'少女帶著寂寞的神情望著窗外。',highlight:'寂しげな'},tip:'描述他人外表透露的情緒，接形容詞語幹；比「そうだ」更書面、文學。',quiz:{blank:'げな',distractors:['がちな','らしい','っぽい']}},{id:'n3-g49',pattern:'〜そうにない',connection:'動詞ます形 ＋ そうにない',meaning:'看樣子不會〜',example:{ja:'この雨はやみそうにない。',zh:'這場雨看來不會停。',highlight:'やみそうにない'},tip:'樣態「そうだ」的否定，表示看起來不太可能；也可說「そうもない」。',quiz:{blank:'そうにない',distractors:['そうだ','ようにない','わけがない']}},{id:'n3-g50',pattern:'〜はずがない',connection:'普通形 ＋ はずがない',meaning:'不可能〜',example:{ja:'あの人が犯人のはずがない。',zh:'那個人不可能是犯人。',highlight:'犯人のはずがない'},tip:'有根據的強烈否定「不可能」；名詞接「の」，與「わけがない」近義。',quiz:{blank:'はずがない',distractors:['はずだ','ようがない','ことがない']}},{id:'n3-g51',pattern:'〜はずだった',connection:'普通形 ＋ はずだった',meaning:'本來應該〜（結果卻沒有）',example:{ja:'彼は八時に来るはずだったが、現れなかった。',zh:'他本來應該八點來，結果卻沒出現。',highlight:'来るはずだった'},tip:'「原本應該〜」但結果不符；與後悔的「べきだった」不同，不表責備。',quiz:{blank:'はずだった',distractors:['はずがなかった','ところだった','ことにした']}},{id:'n3-g52',pattern:'〜べきだ',connection:'動詞辭書形 ＋ べきだ',meaning:'應該〜（義務、道理）',example:{ja:'証拠がない以上、彼を疑うべきではない。',zh:'既然沒有證據，就不應該懷疑他。',highlight:'疑うべきではない'},tip:'表示道理上的義務；「する」可作「すべき」，否定為「べきではない」。',quiz:{blank:'べきではない',distractors:['はずがない','わけではない','ようではない']}},{id:'n3-g53',pattern:'〜べきだった',connection:'動詞辭書形 ＋ べきだった',meaning:'當初應該〜才對',example:{ja:'もっと早く警察に相談するべきだった。',zh:'當初應該早點找警察商量才對。',highlight:'相談するべきだった'},tip:'表示對過去該做而沒做的後悔或責備；與「はずだった」（預定落空）不同。',quiz:{blank:'べきだった',distractors:['ところだった','ことにした','わけだった']}},{id:'n3-g54',pattern:'〜に決まっている',connection:'普通形 ＋ に決まっている',meaning:'一定是〜；肯定〜',example:{ja:'そんなうまい話、うそに決まっている。',zh:'那麼好的事，肯定是騙人的。',highlight:'うそに決まっている'},tip:'說話者主觀強烈斷定「肯定〜」；比「に違いない」更口語。',quiz:{blank:'に決まっている',distractors:['にしている','になっている','に対している']}},{id:'n3-g55',pattern:'〜おそれがある',connection:'動詞辭書形／名詞の ＋ おそれがある',meaning:'恐怕會〜；有〜的危險',example:{ja:'犯人が証拠を隠すおそれがある。',zh:'犯人恐怕會藏匿證據。',highlight:'隠すおそれがある'},tip:'表示有發生壞事的可能，多用於新聞、報告；只用於負面事態。',quiz:{blank:'おそれがある',distractors:['ことがある','わけがある','ところがある']}},{id:'n3-g56',pattern:'〜しかない',connection:'動詞辭書形 ＋ しかない',meaning:'只好〜；只能〜',example:{ja:'電車が止まったので、歩いて帰るしかない。',zh:'電車停駛了，只好走路回家。',highlight:'帰るしかない'},tip:'沒有其他選擇只好〜；接動詞辭書形，近義「ほかない」較書面。',quiz:{blank:'しかない',distractors:['だけない','ことはない','わけがない']}},{id:'n3-g57',pattern:'〜てたまらない',connection:'動詞て形／い形容詞くて／な形容詞で ＋ たまらない',meaning:'〜得受不了',example:{ja:'事件の真相が知りたくてたまらない。',zh:'想知道案件真相想得受不了。',highlight:'知りたくてたまらない'},tip:'表示生理、情緒強烈到受不了，多用第一人稱；不可接單純客觀事實。',quiz:{blank:'てたまらない',distractors:['ても構わない','てはいけない','てばかりいる']}},{id:'n3-g58',pattern:'〜て仕方がない',connection:'動詞て形／い形容詞くて／な形容詞で ＋ 仕方がない',meaning:'非常〜；〜得不得了',example:{ja:'昨夜の物音が気になって仕方がない。',zh:'昨晚的聲響讓我在意得不得了。',highlight:'気になって仕方がない'},tip:'強調感情、感覺強烈到無法控制；「ても仕方がない」則是「〜也沒用」。',quiz:{blank:'仕方がない',distractors:['はいけない','も構わない','ほしい']}},{id:'n3-g59',pattern:'〜ても仕方がない',connection:'動詞て形 ＋ も仕方がない',meaning:'〜也沒用；〜也是沒辦法的',example:{ja:'今さら後悔しても仕方がない。',zh:'事到如今後悔也沒用。',highlight:'後悔しても仕方がない'},tip:'「做了也沒用」帶放棄語氣；注意與「て仕方がない」（非常〜）只差一個「も」。',quiz:{blank:'も仕方がない',distractors:['はいけない','も構わない','ばかりいる']}},{id:'n3-g60',pattern:'〜一方で（對比）',connection:'普通形 ＋ 一方で',meaning:'另一方面〜',example:{ja:'彼は優しい一方で、厳しいところもある。',zh:'他很溫柔，另一方面也有嚴厲的地方。',highlight:'優しい一方で'},tip:'對比同一事物的兩個面向；「反面」偏重正反兩面，一方で也可表同時進行。',quiz:{blank:'一方で',distractors:['うえに','ばかりに','おかげで']}},{id:'n3-g61',pattern:'〜反面',connection:'普通形 ＋ 反面',meaning:'另一方面卻〜',example:{ja:'都会は便利な反面、物価が高い。',zh:'都市雖然方便，另一方面物價卻很高。',highlight:'便利な反面'},tip:'同一事物具有相反的兩面，前後多為正負對比；な形容詞要加「な」。',quiz:{blank:'反面',distractors:['うえに','ために','ついでに']}},{id:'n3-g62',pattern:'〜とは限らない',connection:'普通形 ＋ とは限らない',meaning:'未必〜；不一定〜',example:{ja:'証言がいつも正しいとは限らない。',zh:'證詞未必總是正確的。',highlight:'正しいとは限らない'},tip:'部分否定「不一定〜」，常與「必ずしも」呼應。',quiz:{blank:'とは限らない',distractors:['に決まっている','わけがない','はずだ']}},{id:'n3-g63',pattern:'〜というわけではない',connection:'普通形 ＋ というわけではない',meaning:'並不是說〜',example:{ja:'お金があれば幸せというわけではない。',zh:'並不是說有錢就會幸福。',highlight:'幸せというわけではない'},tip:'婉轉否定前面推論「並不是說〜」；比「わけではない」多一層引述語氣。',quiz:{blank:'というわけではない',distractors:['というわけだ','に決まっている','わけがない']}},{id:'n3-g64',pattern:'〜のではないか',connection:'普通形 ＋ のではないか',meaning:'是不是〜呢？（委婉推測）',example:{ja:'犯人は内部の人間なのではないか。',zh:'犯人會不會是內部的人呢？',highlight:'人間なのではないか'},tip:'委婉表達自己的推測或意見；名詞、な形容詞須加「な」再接「のではないか」。',quiz:{blank:'のではないか',distractors:['じゃないか','ことではないか','はずではないか']}},{id:'n3-g65',pattern:'〜じゃないか',connection:'普通形 ＋ じゃないか',meaning:'不是〜嗎！（責備、確認）',example:{ja:'約束の時間はとっくに過ぎているじゃないか。',zh:'約好的時間不是早就過了嗎！',highlight:'過ぎているじゃないか'},tip:'口語中表示責備、驚訝或要對方確認；句尾音調下降。',quiz:{blank:'じゃないか',distractors:['だろうか','ものか','ことか']}},{id:'n3-g66',pattern:'〜だろうか',connection:'普通形 ＋ だろうか',meaning:'是否〜呢？（疑問）',example:{ja:'彼の言うことは本当なのだろうか。',zh:'他說的話是真的嗎？',highlight:'本当なのだろうか'},tip:'自問式疑問，表示懷疑或不確定；比「か」更委婉，多用於書面、自言自語。',quiz:{blank:'だろうか',distractors:['っけ','ものか','ことか']}},{id:'n3-g67',pattern:'〜ことがある（有時）',connection:'動詞辭書形／ない形 ＋ ことがある',meaning:'有時會〜',example:{ja:'この道は夜になると人が通らないことがある。',zh:'這條路到了晚上有時會沒人經過。',highlight:'通らないことがある'},tip:'表示偶爾發生；與經驗「たことがある」區分，這裡接辭書形或ない形。',quiz:{blank:'ことがある',distractors:['ことにする','ことはない','ことだ']}},{id:'n3-g68',pattern:'〜ことは〜が',connection:'普通形 ＋ ことは ＋ 同一詞 ＋ が',meaning:'〜是〜，但是〜',example:{ja:'読んだことは読んだが、よく分からなかった。',zh:'讀是讀了，但不太懂。',highlight:'読んだことは読んだが'},tip:'同一詞重複「〜是〜，但是」，表示雖然承認前項但結果不理想。',quiz:{blank:'ことは',distractors:['ものは','わけは','ところは']}},{id:'n3-g69',pattern:'〜ことだ（忠告）',connection:'動詞辭書形／ない形 ＋ ことだ',meaning:'最好〜；應該〜',example:{ja:'疲れているなら、早く寝ることだ。',zh:'累的話最好早點睡。',highlight:'早く寝ることだ'},tip:'給予忠告「最好〜」，多為上對下；「ものだ」則表一般常理或應有態度。',quiz:{blank:'ことだ',distractors:['わけだ','はずだ','ところだ']}},{id:'n3-g70',pattern:'〜こと（指示）',connection:'動詞辭書形／ない形 ＋ こと',meaning:'要〜；不得〜（規定、指示）',example:{ja:'現場の物には手を触れないこと。',zh:'不得觸碰現場的物品。',highlight:'手を触れないこと'},tip:'用於規定、注意事項的句尾，表示指示或命令；常見於公告、校規。',quiz:{blank:'こと',distractors:['もの','よう','わけ']}},{id:'n3-g71',pattern:'〜ものだ（本性）',connection:'動詞辭書形／ない形／い形容詞 ＋ ものだ',meaning:'本來就是〜；〜是理所當然的',example:{ja:'人は見かけによらないものだ。',zh:'人本來就不可貌相。',highlight:'見かけによらないものだ'},tip:'表示一般常理或本性；た形＋ものだ則是懷念過去，常考兩者區別。',quiz:{blank:'ものだ',distractors:['ことだ','わけだ','はずだ']}},{id:'n3-g72',pattern:'〜たものだ（回憶）',connection:'動詞た形 ＋ ものだ',meaning:'以前常常〜（懷念）',example:{ja:'子どものころは、よくこの川で遊んだものだ。',zh:'小時候常常在這條河邊玩。',highlight:'遊んだものだ'},tip:'回憶過去常做的事，常與「よく」呼應；與表示本性的「ものだ」區分。',quiz:{blank:'ものだ',distractors:['ことだ','わけだ','ところだ']}},{id:'n3-g73',pattern:'〜ものではない',connection:'動詞辭書形 ＋ ものではない',meaning:'不應該〜（勸誡）',example:{ja:'人の手紙を勝手に読むものではない。',zh:'不應該擅自看別人的信。',highlight:'読むものではない'},tip:'以常理勸誡「不應該〜」，語氣比「べきではない」柔和。',quiz:{blank:'ものではない',distractors:['ことではない','わけではない','はずではない']}},{id:'n3-g74',pattern:'〜もの（理由）',connection:'普通形 ＋ もの',meaning:'因為〜嘛（辯解）',example:{ja:'だって、知らなかったんだもの。',zh:'因為我不知道嘛。',highlight:'知らなかったんだもの'},tip:'口語中辯解理由，多為女性或小孩使用，常與「だって」呼應。',quiz:{blank:'もの',distractors:['こと','わけ','はず']}},{id:'n3-g75',pattern:'〜ものだから',connection:'普通形 ＋ ものだから',meaning:'因為〜（辯解理由）',example:{ja:'道が混んでいたものだから、遅れてしまった。',zh:'因為路上塞車，所以遲到了。',highlight:'混んでいたものだから'},tip:'辯解理由，後句不接命令、請求；口語可說「もんだから」。',quiz:{blank:'ものだから',distractors:['ものの','くせに','ところで']}},{id:'n3-g76',pattern:'〜ところに',connection:'動詞辭書形／ている形／た形 ＋ ところに',meaning:'正當〜的時候（發生某事）',example:{ja:'出かけようとしているところに、客が来た。',zh:'正要出門的時候，客人來了。',highlight:'出かけようとしているところに'},tip:'正當〜時發生某事（多為打擾）；與「ところへ」幾乎同義，へ較強調有人來。',quiz:{blank:'ところに',distractors:['ところを','とたんに','ついでに']}},{id:'n3-g77',pattern:'〜ところへ',connection:'動詞辭書形／ている形／た形 ＋ ところへ',meaning:'正當〜時（有人來或事發生）',example:{ja:'話をしているところへ、刑事が入ってきた。',zh:'正在說話時，刑警走了進來。',highlight:'話をしているところへ'},tip:'後句多為「来る・入る」等移動動詞；「ところを」則接被看到、被抓等。',quiz:{blank:'ところへ',distractors:['ところを','とたんに','ついでに']}},{id:'n3-g78',pattern:'〜たところ（結果）',connection:'動詞た形 ＋ ところ',meaning:'〜之後，結果〜',example:{ja:'調べてみたところ、指紋が見つかった。',zh:'調查之後，結果找到了指紋。',highlight:'調べてみたところ'},tip:'做了某事後得到某結果，後句為過去式；不可用於說話者能控制的結果。',quiz:{blank:'ところ',distractors:['ばかり','まま','きり']}},{id:'n3-g79',pattern:'〜ところだった',connection:'動詞辭書形 ＋ ところだった',meaning:'差一點就〜',example:{ja:'もう少しで犯人を見逃すところだった。',zh:'差一點就讓犯人溜走了。',highlight:'見逃すところだった'},tip:'差一點就發生（實際沒發生），常與「もう少しで」呼應。',quiz:{blank:'ところだった',distractors:['べきだった','はずだった','ことだった']}},{id:'n3-g80',pattern:'〜てからでないと',connection:'動詞て形 ＋ からでないと',meaning:'不先〜的話就不能〜',example:{ja:'現場を見てからでないと、何とも言えない。',zh:'不先看過現場的話，什麼都說不準。',highlight:'見てからでないと'},tip:'不先做A就不能做B，後句多為否定或困難表現。',quiz:{blank:'からでないと',distractors:['からといって','ばかりでないと','からこそ']}},{id:'n3-g81',pattern:'〜て以来',connection:'動詞て形 ＋ 以来',meaning:'自從〜以來',example:{ja:'あの事件が起きて以来、彼は口を閉ざしている。',zh:'自從那起案件發生以來，他一直沉默不語。',highlight:'起きて以来'},tip:'自從某事後一直持續至今，後句為持續狀態；不用於近期短暫的事。',quiz:{blank:'以来',distractors:['以上','以外','以内']}},{id:'n3-g82',pattern:'〜たきり',connection:'動詞た形 ＋ きり',meaning:'〜之後就再也沒有〜',example:{ja:'兄は家を出たきり、帰ってこない。',zh:'哥哥離家之後就再也沒有回來。',highlight:'出たきり'},tip:'做了某事後就再也沒有下文，後句多為否定；與「たまま」近義但更強調沒變化。',quiz:{blank:'きり',distractors:['ばかり','とたん','ほど']}},{id:'n3-g83',pattern:'〜きり（只有）',connection:'名詞 ＋ きり',meaning:'只有〜；僅〜',example:{ja:'二人きりで話したいことがある。',zh:'有件事想跟你單獨兩個人談談。',highlight:'二人きり'},tip:'「只有〜」限定數量；口語可說「っきり」，如「二人っきり」。',quiz:{blank:'きり',distractors:['まで','ほど','ずつ']}},{id:'n3-g84',pattern:'〜まで（甚至）',connection:'名詞 ＋ まで',meaning:'連〜都；甚至〜',example:{ja:'子どもにまでばかにされた。',zh:'連小孩子都瞧不起我。',highlight:'子どもにまで'},tip:'舉極端例子「連〜都」，常帶意外感；與「さえ」相近。',quiz:{blank:'まで',distractors:['だけ','しか','ほど']}},{id:'n3-g85',pattern:'〜ごとに',connection:'名詞／動詞辭書形 ＋ ごとに',meaning:'每〜；每隔〜',example:{ja:'この時計は一時間ごとに鳴る。',zh:'這個時鐘每一小時響一次。',highlight:'一時間ごとに'},tip:'「每〜」，以單位重複；與「おきに」在時間單位時意思相近。',quiz:{blank:'ごとに',distractors:['たびに','ぶりに','までに']}},{id:'n3-g86',pattern:'〜を通して',connection:'名詞 ＋ を通して',meaning:'透過〜；在整個〜期間',example:{ja:'友人を通して彼と知り合った。',zh:'透過朋友認識了他。',highlight:'友人を通して'},tip:'表示媒介「透過〜」或時間範圍「整個〜期間」；近義「を通じて」。',quiz:{blank:'を通して',distractors:['をもとに','を中心に','に対して']}},{id:'n3-g87',pattern:'〜とともに',connection:'名詞／動詞辭書形 ＋ とともに',meaning:'和〜一起；隨著〜',example:{ja:'時代とともに、犯罪の手口も変わってきた。',zh:'隨著時代變遷，犯罪手法也改變了。',highlight:'時代とともに'},tip:'有「一起」與「隨著（變化）」兩義；表變化時與「につれて」相近。',quiz:{blank:'とともに',distractors:['として','について','にとって']}},{id:'n3-g88',pattern:'〜に従って',connection:'名詞／動詞辭書形 ＋ に従って',meaning:'按照〜；隨著〜',example:{ja:'上に行くに従って、空気が薄くなる。',zh:'越往上走，空氣越稀薄。',highlight:'行くに従って'},tip:'有「遵照」與「隨著」兩義；表隨著變化時與「につれて」可互換。',quiz:{blank:'に従って',distractors:['にとって','に対して','について']}},{id:'n3-g89',pattern:'〜による',connection:'名詞 ＋ による ＋ 名詞',meaning:'由〜引起的；由〜進行的',example:{ja:'台風による被害は大きかった。',zh:'颱風造成的災害很大。',highlight:'台風による'},tip:'修飾名詞的形態「由〜造成的〜」；連接動詞時用「によって」。',quiz:{blank:'による',distractors:['によって','にとって','について']}},{id:'n3-g90',pattern:'〜によっては',connection:'名詞 ＋ によっては',meaning:'視〜情況，有的〜',example:{ja:'場合によっては、警察に知らせることになる。',zh:'視情況而定，有可能會通知警察。',highlight:'場合によっては'},tip:'表示「依情況不同，有的會〜」，強調特定情形；比「によって」多了限定語感。',quiz:{blank:'によっては',distractors:['にとっては','に対しては','については']}},{id:'n3-g91',pattern:'〜に関する',connection:'名詞 ＋ に関する ＋ 名詞',meaning:'有關〜的',example:{ja:'事件に関する情報を集めている。',zh:'正在蒐集有關案件的情報。',highlight:'事件に関する'},tip:'「に関して」的連體形，後接名詞；「について」修飾名詞則是「についての」。',quiz:{blank:'に関する',distractors:['に関して','に対して','にとって']}},{id:'n3-g92',pattern:'〜から〜にかけて',connection:'名詞 ＋ から ＋ 名詞 ＋ にかけて',meaning:'從〜到〜（大致範圍）',example:{ja:'犯行は夜十時から十二時にかけて行われた。',zh:'犯案時間大約在晚上十點到十二點之間。',highlight:'十時から十二時にかけて'},tip:'表示大致範圍，不像「から〜まで」有明確起訖點。',quiz:{blank:'にかけて',distractors:['に対して','において','につれて']}},{id:'n3-g93',pattern:'〜にかわって',connection:'名詞 ＋ にかわって',meaning:'代替〜',example:{ja:'社長にかわって、私がご説明します。',zh:'由我代替社長為您說明。',highlight:'社長にかわって'},tip:'名詞＋にかわって＝代替某人；「かわりに」還有「交換」意義。',quiz:{blank:'にかわって',distractors:['にとって','に対して','に関して']}},{id:'n3-g94',pattern:'〜を中心に',connection:'名詞 ＋ を中心に',meaning:'以〜為中心',example:{ja:'捜査は駅周辺を中心に行われた。',zh:'搜查以車站周邊為中心進行。',highlight:'駅周辺を中心に'},tip:'以某物為中心或重點，修飾名詞時用「を中心とした」。',quiz:{blank:'を中心に',distractors:['をもとに','を通して','を込めて']}},{id:'n3-g95',pattern:'〜をもとに',connection:'名詞 ＋ をもとに',meaning:'以〜為基礎；根據〜',example:{ja:'目撃者の証言をもとに似顔絵を作った。',zh:'根據目擊者的證詞畫出了肖像圖。',highlight:'証言をもとに'},tip:'以〜為素材、基礎創作；與「に基づいて」相近，後者更強調依據。',quiz:{blank:'をもとに',distractors:['を込めて','に向けて','に向かって']}},{id:'n3-g96',pattern:'〜を込めて',connection:'名詞 ＋ を込めて',meaning:'滿懷〜；傾注〜',example:{ja:'感謝の気持ちを込めて手紙を書いた。',zh:'滿懷感謝之情寫了信。',highlight:'気持ちを込めて'},tip:'傾注感情，多接「心・愛・気持ち」等；修飾名詞為「を込めた」。',quiz:{blank:'を込めて',distractors:['を中心に','に向かって','に加えて']}},{id:'n3-g97',pattern:'〜に向けて',connection:'名詞 ＋ に向けて',meaning:'朝向〜；為了〜（目標）',example:{ja:'試験に向けて毎日勉強している。',zh:'為了考試每天都在唸書。',highlight:'試験に向けて'},tip:'朝向目標努力準備；「に向かって」偏重物理方向，常考兩者區別。',quiz:{blank:'に向けて',distractors:['にとって','によって','に関して']}},{id:'n3-g98',pattern:'〜に向かって',connection:'名詞 ＋ に向かって',meaning:'向著〜；朝〜',example:{ja:'男は出口に向かって走り出した。',zh:'男子朝著出口跑了出去。',highlight:'出口に向かって'},tip:'表示實際的方向或面對對象；為目標準備時多用「に向けて」。',quiz:{blank:'に向かって',distractors:['に対して','にとって','によって']}},{id:'n3-g99',pattern:'〜向き',connection:'名詞 ＋ 向き',meaning:'適合〜的',example:{ja:'この推理小説は初心者向きだ。',zh:'這本推理小說適合初學者。',highlight:'初心者向き'},tip:'「適合〜」，結果剛好合適；「向け」是一開始就以〜為對象製作。',quiz:{blank:'向き',distractors:['っぽい','がち','だらけ']}},{id:'n3-g100',pattern:'〜向け',connection:'名詞 ＋ 向け',meaning:'以〜為對象的；專為〜',example:{ja:'これは子ども向けの探偵アニメだ。',zh:'這是給小孩看的偵探動畫。',highlight:'子ども向け'},tip:'以〜為對象而特別製作；「向き」則表示剛好適合，常考兩者對比。',quiz:{blank:'向け',distractors:['だらけ','がち','ぎみ']}},{id:'n3-g101',pattern:'〜において',connection:'名詞 ＋ において',meaning:'在〜（場所、時間、領域）',example:{ja:'会議は第一会議室において行われる。',zh:'會議在第一會議室舉行。',highlight:'第一会議室において'},tip:'「で」的書面語，表場所、時間、領域；修飾名詞用「における」。',quiz:{blank:'において',distractors:['にとって','に対して','について']}},{id:'n3-g102',pattern:'〜における',connection:'名詞 ＋ における ＋ 名詞',meaning:'在〜的',example:{ja:'現代社会における犯罪の特徴を調べる。',zh:'調查現代社會中犯罪的特徵。',highlight:'現代社会における'},tip:'「において」的連體形，後接名詞，多用於書面正式文章。',quiz:{blank:'における',distractors:['において','にとって','について']}},{id:'n3-g103',pattern:'〜に加えて',connection:'名詞 ＋ に加えて',meaning:'加上〜；除了〜之外還〜',example:{ja:'雨に加えて風も強くなってきた。',zh:'除了下雨，風也變強了。',highlight:'雨に加えて'},tip:'表示在前項之外再加上後項，常與「も」呼應；比「うえに」書面。',quiz:{blank:'に加えて',distractors:['に比べて','によって','にとって']}},{id:'n3-g104',pattern:'〜うえ（に）',connection:'普通形／名詞の ＋ うえに',meaning:'不僅〜而且〜',example:{ja:'あの店は安いうえに、味もいい。',zh:'那家店不僅便宜，味道也好。',highlight:'安いうえに'},tip:'前後須同為正面或同為負面；正負對比時要用「反面」或「のに」。',quiz:{blank:'うえに',distractors:['反面','くせに','せいで']}},{id:'n3-g105',pattern:'〜ばかりでなく',connection:'普通形／名詞 ＋ ばかりでなく',meaning:'不只〜還〜',example:{ja:'彼は英語ばかりでなく、中国語も話せる。',zh:'他不只會說英語，還會說中文。',highlight:'英語ばかりでなく'},tip:'與「だけでなく」同義，後句常用「も」；較書面。',quiz:{blank:'ばかりでなく',distractors:['かわりに','として','によって']}},{id:'n3-g106',pattern:'〜はもちろん',connection:'名詞 ＋ はもちろん',meaning:'〜就不用說了，連〜也',example:{ja:'この事件は日本はもちろん、海外でも報道された。',zh:'這起案件在日本就不用說了，連海外都有報導。',highlight:'日本はもちろん'},tip:'前項理所當然，後項也一樣，後句常用「も」；比「だけでなく」更強調前項當然。',quiz:{blank:'はもちろん',distractors:['にとって','について','として']}},{id:'n3-g107',pattern:'〜とか〜とか',connection:'名詞／普通形 ＋ とか ＋ 名詞／普通形 ＋ とか',meaning:'〜啦〜啦（列舉）',example:{ja:'休みの日は映画とか買い物とかに行く。',zh:'假日會去看電影啦、買東西啦。',highlight:'映画とか買い物とか'},tip:'口語中舉例，暗示還有其他；比「〜や〜など」更隨意。',quiz:{blank:'とかに',distractors:['やに','なりに','だけに']}},{id:'n3-g108',pattern:'〜だけ（盡量）',connection:'動詞辭書形／可能形／い形容詞／な形容詞な ＋ だけ',meaning:'盡量〜；能〜多少就〜多少',example:{ja:'好きなだけ食べてください。',zh:'請盡量吃，想吃多少吃多少。',highlight:'好きなだけ'},tip:'表示「盡可能〜」，常見「できるだけ・好きなだけ・欲しいだけ」。',quiz:{blank:'だけ',distractors:['ほど','まで','ばかり']}},{id:'n3-g109',pattern:'〜さえ',connection:'名詞 ＋ さえ',meaning:'連〜都',example:{ja:'あまりに忙しくて、食事をする時間さえない。',zh:'忙到連吃飯的時間都沒有。',highlight:'時間さえ'},tip:'舉極端例子表示「連〜都」，多接否定；「まで」較常用於肯定句。',quiz:{blank:'さえ',distractors:['しか','だけ','ばかり']}},{id:'n3-g110',pattern:'〜さえ〜ば',connection:'名詞 ＋ さえ ＋ 動詞ば形',meaning:'只要〜就〜',example:{ja:'この鍵さえあれば、金庫は開けられる。',zh:'只要有這把鑰匙，就能打開保險箱。',highlight:'この鍵さえあれば'},tip:'「只要〜就〜」，強調唯一必要條件；動詞用「ます形＋さえすれば」。',quiz:{blank:'さえ',distractors:['しか','まで','ほど']}},{id:'n3-g111',pattern:'〜こそ',connection:'名詞 ＋ こそ',meaning:'正是〜；才是〜',example:{ja:'今度こそ真犯人を捕まえてみせる。',zh:'這次一定要抓到真正的犯人。',highlight:'今度こそ'},tip:'「今度こそ」「こちらこそ」為常考固定說法；こそ強調「正是這個」，不與否定的しか混淆。',quiz:{blank:'こそ',distractors:['さえ','しか','ほど']}},{id:'n3-g112',pattern:'〜なんか（輕視）',connection:'名詞 ＋ なんか',meaning:'〜之類的（輕視、謙虛）',example:{ja:'僕なんかにこの事件が解けるはずがない。',zh:'像我這種人不可能解得開這個案子。',highlight:'僕なんか'},tip:'なんか是など的口語，用於自己表謙虛、用於他人表輕視；常與「〜ない」「〜はずがない」連用。',quiz:{blank:'なんか',distractors:['こそ','さえ','ほど']}},{id:'n3-g113',pattern:'〜なんて（驚訝）',connection:'普通形／名詞 ＋ なんて',meaning:'竟然〜；〜什麼的（意外、輕視）',example:{ja:'あの優しい彼が犯人だったなんて。',zh:'那個溫柔的他竟然是犯人。',highlight:'犯人だったなんて'},tip:'接在句尾表驚訝、意外，後面常省略「驚いた」；なんか不能這樣接在普通形句尾表驚訝。',quiz:{blank:'なんて',distractors:['なんか','こそ','さえ']}},{id:'n3-g114',pattern:'〜など（委婉）',connection:'名詞 ＋ など',meaning:'〜之類的（委婉提議）',example:{ja:'お茶などいかがですか。',zh:'要不要喝點茶之類的呢？',highlight:'お茶など'},tip:'「〜などいかがですか」為委婉提議的客氣說法，口語可換成「〜でも」或「〜なんか」。',quiz:{blank:'など',distractors:['こそ','しか','さえ']}},{id:'n3-g115',pattern:'〜くらい（輕視）',connection:'普通形／名詞 ＋ くらい',meaning:'區區〜；至少〜（最低限度）',example:{ja:'自分の部屋くらい自分で掃除しなさい。',zh:'至少自己的房間要自己打掃。',highlight:'自分の部屋くらい'},tip:'表「這點小事至少要做到」，常接命令、義務；表最低限度時不能換成「ほど」。',quiz:{blank:'くらい',distractors:['ほど','しか','ばかりか']}},{id:'n3-g116',pattern:'〜くらいだ（程度）',connection:'普通形 ＋ くらいだ',meaning:'甚至到〜的程度',example:{ja:'足が痛くて、歩けないくらいだ。',zh:'腳痛到幾乎走不了路。',highlight:'歩けないくらいだ'},tip:'以具體例子說明程度之高；可換成「ほどだ」，但「〜ほどだ」語氣較書面。',quiz:{blank:'くらいだ',distractors:['ばかりだ','ところだ','はずだ']}},{id:'n3-g117',pattern:'〜ほど〜はない',connection:'名詞 ＋ ほど ＋ 名詞 ＋ はない',meaning:'沒有比〜更〜的',example:{ja:'彼ほど頭の切れる探偵はいない。',zh:'沒有比他頭腦更敏銳的偵探了。',highlight:'彼ほど'},tip:'「AほどBはない」＝A最B；也可說「Aくらい〜はない」。主語是人時用「いない」。',quiz:{blank:'ほど',distractors:['こそ','まで','さえ']}},{id:'n3-g118',pattern:'〜ほど（大約）',connection:'數量詞 ＋ ほど',meaning:'大約〜',example:{ja:'駅から十分ほど歩いた所に、その家がある。',zh:'那棟房子在從車站步行約十分鐘的地方。',highlight:'十分ほど'},tip:'數量詞＋ほど表大約，與「ばかり」「くらい」可互換；表時間點的「大約」要用「ごろ」。',quiz:{blank:'ほど',distractors:['ごろ','おきに','ずつ']}},{id:'n3-g119',pattern:'〜ばかり（大約）',connection:'數量詞 ＋ ばかり',meaning:'大約〜；〜左右',example:{ja:'一週間ばかり旅行に出かけていた。',zh:'出門旅行了大約一個星期。',highlight:'一週間ばかり'},tip:'數量詞＋ばかり＝大約，與「動詞た形＋ばかり（剛〜）」「〜てばかりいる（老是）」區分。',quiz:{blank:'ばかり',distractors:['ごろ','おきに','ずつ']}},{id:'n3-g120',pattern:'〜も（數量強調）',connection:'數量詞 ＋ も',meaning:'竟有〜之多',example:{ja:'犯人は三時間も黙ったままだった。',zh:'犯人竟然沉默了三個小時之久。',highlight:'三時間も'},tip:'數量詞＋も強調「多」；數量詞＋しか＋否定則強調「少」，兩者常一起出題對比。',quiz:{blank:'も',distractors:['しか','ごろ','おきに']}},{id:'n3-g121',pattern:'〜でも（舉例）',connection:'名詞 ＋ でも',meaning:'〜之類的（舉例提議）',example:{ja:'コーヒーでも飲みませんか。',zh:'要不要喝杯咖啡什麼的？',highlight:'コーヒーでも'},tip:'名詞＋でも用於舉例、委婉提議或邀約（〜でも飲みませんか），並非「即使」。',quiz:{blank:'でも',distractors:['こそ','しか','さえ']}},{id:'n3-g122',pattern:'〜でも（任何）',connection:'疑問詞 ＋ でも',meaning:'無論〜都',example:{ja:'困ったことがあったら、いつでも連絡してください。',zh:'遇到困難的話，隨時都可以聯絡我。',highlight:'いつでも'},tip:'疑問詞＋でも＝全面肯定（いつでも、だれでも）；疑問詞＋か＝不確定（いつか、だれか）。',quiz:{blank:'でも',distractors:['か','まで','ごろ']}},{id:'n3-g123',pattern:'〜には（目的）',connection:'動詞辭書形 ＋ には',meaning:'要〜的話；為了〜',example:{ja:'この謎を解くには、もっと情報が必要だ。',zh:'要解開這個謎，需要更多情報。',highlight:'解くには'},tip:'「動詞辭書形＋には」後接必要、需要、困難等評價句；意思近「〜ためには」。',quiz:{blank:'には',distractors:['ので','けれど','ほど']}},{id:'n3-g124',pattern:'〜には（對〜而言）',connection:'名詞 ＋ には',meaning:'對〜來說',example:{ja:'この問題は子どもには難しすぎる。',zh:'這個問題對小孩子來說太難了。',highlight:'子どもには'},tip:'「名詞＋には＋評價（難しい／無理）」表對某人而言；「にとって」語意相近但較書面。',quiz:{blank:'には',distractors:['から','しか','ほど']}},{id:'n3-g125',pattern:'〜と違って',connection:'名詞 ＋ と違って',meaning:'和〜不同',example:{ja:'兄と違って、弟はとても静かだ。',zh:'和哥哥不同，弟弟非常安靜。',highlight:'兄と違って'},tip:'「AとBは違う」的副詞子句形，修飾名詞時用「〜と違う＋名詞」。',quiz:{blank:'と違って',distractors:['と同じく','のように','として']}},{id:'n3-g126',pattern:'〜ながら（逆接）',connection:'動詞ます形／い形容詞／名詞 ＋ ながら',meaning:'雖然〜但是〜',example:{ja:'悪いと知りながら、うそをついてしまった。',zh:'雖然知道不對，卻還是說了謊。',highlight:'知りながら'},tip:'逆接ながら多接「知る、残念、狭い、子ども」等狀態性詞；與表同時動作的ながら區分。',quiz:{blank:'ながら',distractors:['たい','かけて','そうで']}},{id:'n3-g127',pattern:'〜としても',connection:'普通形 ＋ としても',meaning:'即使〜也',example:{ja:'たとえ証拠があったとしても、彼は認めないだろう。',zh:'即使有證據，他大概也不會承認吧。',highlight:'あったとしても'},tip:'「としても」是假設讓步（即使〜也），「としたら」是假設條件（如果〜的話），常互為干擾選項。',quiz:{blank:'としても',distractors:['としたら','ので','から']}},{id:'n3-g128',pattern:'たとえ〜ても',connection:'たとえ ＋ 動詞て形／い形容詞くて ＋ も；名詞／な形容詞 ＋ でも',meaning:'即使〜也',example:{ja:'たとえ失敗しても、もう一度挑戦する。',zh:'即使失敗了，也要再挑戰一次。',highlight:'たとえ失敗しても'},tip:'「たとえ」必須呼應「〜ても／でも」，不能接「〜たら」「〜ば」。',quiz:{blank:'ても',distractors:['たら','ながら','たのに']}},{id:'n3-g129',pattern:'いくら〜ても',connection:'いくら ＋ 動詞て形 ＋ も',meaning:'無論怎麼〜也',example:{ja:'いくら探しても、凶器は見つからなかった。',zh:'無論怎麼找，都找不到凶器。',highlight:'いくら探しても'},tip:'「いくら〜ても」強調再怎麼努力也無效，後句多為否定或不如意的結果。',quiz:{blank:'ても',distractors:['たら','ながら','たので']}},{id:'n3-g130',pattern:'どんなに〜ても',connection:'どんなに ＋ 動詞て形／い形容詞くて ＋ も；な形容詞／名詞 ＋ でも',meaning:'不管多麼〜也',example:{ja:'どんなに忙しくても、朝ごはんは食べる。',zh:'不管多忙，早餐都會吃。',highlight:'どんなに忙しくても'},tip:'「どんなに」須呼應「〜ても」；「どんなに〜だろう」則是感嘆用法，勿混淆。',quiz:{blank:'くても',distractors:['かったら','いので','ければ']}},{id:'n3-g131',pattern:'〜たって',connection:'動詞た形 ＋ って／い形容詞く ＋ たって',meaning:'即使〜也（口語）',example:{ja:'今から走ったって、もう間に合わない。',zh:'就算現在跑也來不及了。',highlight:'走ったって'},tip:'「〜たって」是「〜ても」的口語；名詞、な形容詞用「〜だって」。',quiz:{blank:'たって',distractors:['たら','たので','たのに']}},{id:'n3-g132',pattern:'〜だって（即使）',connection:'名詞 ＋ だって',meaning:'就連〜也；即使是〜也（口語）',example:{ja:'子どもだって、それくらい分かる。',zh:'就連小孩子也懂那種事。',highlight:'子どもだって'},tip:'名詞＋だって＝「〜でも」的口語，意為就連〜也；句首的「だって」則是「可是、因為」。',quiz:{blank:'だって',distractors:['しか','こそ','ほど']}},{id:'n3-g133',pattern:'〜どおり',connection:'名詞 ＋ どおり',meaning:'按照〜；如同〜',example:{ja:'事件は予想どおりの結末を迎えた。',zh:'案件迎來了如預期的結局。',highlight:'予想どおり'},tip:'名詞直接接「どおり」（濁音）；動詞或「名詞の」後接「とおり」（清音）。',quiz:{blank:'どおり',distractors:['ごと','ぶり','だらけ']}},{id:'n3-g134',pattern:'〜せいか',connection:'普通形／名詞の ＋ せいか',meaning:'也許是因為〜',example:{ja:'寝不足のせいか、頭が痛い。',zh:'也許是因為睡眠不足，頭很痛。',highlight:'寝不足のせいか'},tip:'「せいか」表不確定的原因，多用於負面結果；正面結果用「おかげか」。',quiz:{blank:'せいか',distractors:['くせに','わりに','ように']}},{id:'n3-g135',pattern:'〜のは〜からだ',connection:'普通形 ＋ のは ＋ 普通形 ＋ からだ',meaning:'之所以〜是因為〜',example:{ja:'彼が嘘をついたのは、家族を守りたかったからだ。',zh:'他之所以說謊，是因為想保護家人。',highlight:'守りたかったからだ'},tip:'「〜のは〜からだ」強調理由，句尾不能換成「ので」；「ためだ」則可替換。',quiz:{blank:'からだ',distractors:['ので','のに','ところだ']}},{id:'n3-g136',pattern:'なぜなら〜からだ',connection:'なぜなら ＋ 普通形 ＋ からだ',meaning:'因為〜（說明理由）',example:{ja:'彼は犯人ではない。なぜなら、その時海外にいたからだ。',zh:'他不是犯人，因為那時他人在國外。',highlight:'なぜなら'},tip:'「なぜなら」放在後句開頭並與句尾「〜からだ／〜ためだ」呼應；「だから」則接結果。',quiz:{blank:'なぜなら',distractors:['だから','それなのに','ところが']}},{id:'n3-g137',pattern:'〜結果',connection:'動詞た形／名詞の ＋ 結果',meaning:'〜的結果',example:{ja:'調査した結果、意外な事実が分かった。',zh:'調查的結果，發現了意想不到的事實。',highlight:'調査した結果'},tip:'「〜た結果」後接經過努力或行動後得到的結論；與「〜たところ」意思相近。',quiz:{blank:'結果',distractors:['とたん','うちに','最中に']}},{id:'n3-g138',pattern:'〜てはじめて',connection:'動詞て形 ＋ はじめて',meaning:'〜之後才〜',example:{ja:'失ってはじめて、その大切さに気づいた。',zh:'失去之後才察覺到它的重要。',highlight:'失ってはじめて'},tip:'「〜てはじめて」強調經歷某事後才第一次意識到，後句常為「気づく、分かる」。',quiz:{blank:'はじめて',distractors:['も','ばかり','おいて']}},{id:'n3-g139',pattern:'〜と同時に',connection:'動詞辭書形／名詞 ＋ と同時に',meaning:'在〜的同時',example:{ja:'ドアが開くと同時に、銃声が聞こえた。',zh:'門打開的同時，聽到了槍聲。',highlight:'開くと同時に'},tip:'接動詞辭書形或名詞；「とたん（に）」須接た形且帶意外感，常用來比較。',quiz:{blank:'と同時に',distractors:['とたんに','うちに','最中に']}},{id:'n3-g140',pattern:'〜あたり',connection:'數量詞 ＋ あたり',meaning:'每〜',example:{ja:'一人あたり三千円かかる。',zh:'每人要花三千日圓。',highlight:'一人あたり'},tip:'「〜あたり」表每單位的比率，書面可說「〜につき」；「〜ずつ」表平均分配的數量。',quiz:{blank:'あたり',distractors:['ぶり','おきに','ずつ']}},{id:'n3-g141',pattern:'〜なきゃ',connection:'動詞ない形（去ない）＋ なきゃ（ならない）',meaning:'不〜不行（口語）',example:{ja:'もう帰らなきゃ。母が心配してる。',zh:'得回去了，我媽會擔心。',highlight:'帰らなきゃ'},tip:'「なきゃ」＝「なければ」的縮約，後面常省略「ならない」；女性、口語常見。',quiz:{blank:'なきゃ',distractors:['ないで','なくて','ず']}},{id:'n3-g142',pattern:'〜なくちゃ',connection:'動詞ない形（去ない）＋ なくちゃ（いけない）',meaning:'必須〜（口語）',example:{ja:'明日までにレポートを出さなくちゃ。',zh:'明天之前得交報告才行。',highlight:'出さなくちゃ'},tip:'「なくちゃ」＝「なくては」的縮約，後省略「いけない」，與「なきゃ」意思相同。',quiz:{blank:'なくちゃ',distractors:['ないで','なくて','ず']}},{id:'n3-g143',pattern:'〜てる',connection:'動詞て形 ＋ る（〜ている的口語）',meaning:'正在〜；〜著（口語）',example:{ja:'あの人、さっきからこっちを見てる。',zh:'那個人從剛才就一直在看這邊。',highlight:'見てる'},tip:'「〜ている→〜てる」「〜ていた→〜てた」；「〜でいる」則縮約成「〜でる」。',quiz:{blank:'てる',distractors:['たい','よう','ろ']}},{id:'n3-g144',pattern:'〜って（主題）',connection:'名詞 ＋ って',meaning:'所謂〜；〜這個（口語提示主題）',example:{ja:'探偵って、思ったより地味な仕事だね。',zh:'偵探這行，比想像中還要樸素呢。',highlight:'探偵って'},tip:'名詞＋って＝「〜というのは／〜は」的口語，用於提出話題或下定義。',quiz:{blank:'って',distractors:['しか','ほど','さえ']}},{id:'n3-g145',pattern:'〜って（引用）',connection:'普通形 ＋ って ＋ 言う／思う',meaning:'（說）〜（口語引用）',example:{ja:'彼、明日は来られないって言ってたよ。',zh:'他說明天不能來喔。',highlight:'来られないって言ってた'},tip:'引用的「って」＝「と」的口語，「〜って言ってた」常用來轉述他人的話。',quiz:{blank:'って言ってた',distractors:['から言ってた','ので言ってた','ほど言ってた']}},{id:'n3-g146',pattern:'〜っていう',connection:'名詞 ＋ っていう ＋ 名詞',meaning:'叫做〜的（口語）',example:{ja:'田中さんっていう人から電話があったよ。',zh:'有個叫田中的人打電話來喔。',highlight:'田中さんっていう'},tip:'「〜っていう＋名詞」＝「〜という」的口語，用於介紹對方不熟悉的名稱。',quiz:{blank:'っていう',distractors:['みたいな','らしい','のような']}},{id:'n3-g147',pattern:'〜んだって',connection:'普通形 ＋ んだって',meaning:'聽說〜呢（口語傳聞）',example:{ja:'あの屋敷、昔は病院だったんだって。',zh:'聽說那棟宅邸以前是醫院呢。',highlight:'病院だったんだって'},tip:'「んだって」表傳聞，常用語尾上揚；名詞、な形容詞現在式要用「〜なんだって」。',quiz:{blank:'んだって',distractors:['っけ','のに','ので']}},{id:'n3-g148',pattern:'〜じゃん',connection:'普通形 ＋ じゃん',meaning:'不是〜嘛（口語確認）',example:{ja:'なんだ、ちゃんとできるじゃん。',zh:'什麼嘛，你不是做得很好嗎。',highlight:'できるじゃん'},tip:'「じゃん」＝「じゃないか」的口語，表確認或發現；語調下降，並非否定。',quiz:{blank:'じゃん',distractors:['っけ','かな','ので']}},{id:'n3-g149',pattern:'〜んじゃない？',connection:'普通形 ＋ んじゃない',meaning:'應該是〜吧？（口語推測）',example:{ja:'それ、彼の忘れ物なんじゃない？',zh:'那個應該是他忘了帶走的東西吧？',highlight:'忘れ物なんじゃない'},tip:'語尾上揚的「〜んじゃない？」表推測；名詞、な形容詞要加「な」（〜なんじゃない）。',quiz:{blank:'んじゃない',distractors:['のに','ので','わけがない']}},{id:'n3-g150',pattern:'〜わ',connection:'普通形 ＋ わ',meaning:'〜呢；〜啊（女性語氣、感嘆）',example:{ja:'まあ、きれいな花だわ。',zh:'哇，好漂亮的花啊。',highlight:'花だわ'},tip:'句尾「わ」表女性柔和感嘆，關西方言男女皆用；「ぞ」「ぜ」則是男性語氣。',quiz:{blank:'わ',distractors:['っけ','か','ろう']}},{id:'n3-g151',pattern:'〜ぞ',connection:'普通形 ＋ ぞ',meaning:'〜喔！（男性語氣、強調）',example:{ja:'気をつけろ、だれか来るぞ。',zh:'小心，有人來了！',highlight:'来るぞ'},tip:'「ぞ」為男性強烈語氣，用於提醒、警告或自我激勵；對長輩不使用。',quiz:{blank:'ぞ',distractors:['っけ','か','な']}},{id:'n3-g152',pattern:'〜てごらん',connection:'動詞て形 ＋ ごらん',meaning:'〜看看吧（對晚輩）',example:{ja:'この写真をよく見てごらん。',zh:'仔細看看這張照片吧。',highlight:'見てごらん'},tip:'「〜てごらん」是「〜てみなさい」的委婉說法，只用於對晚輩或小孩。',quiz:{blank:'ごらん',distractors:['いる','しまう','ある']}},{id:'n3-g153',pattern:'〜たら？（建議）',connection:'動詞た形 ＋ ら',meaning:'〜如何？；不如〜吧（口語建議）',example:{ja:'そんなに気になるなら、本人に聞いてみたら？',zh:'既然那麼在意，不如直接問本人？',highlight:'聞いてみたら'},tip:'句尾的「〜たら？」是「〜たらどう？」的省略，表輕鬆的建議。',quiz:{blank:'たら',distractors:['ので','ながら','たり']}},{id:'n3-g154',pattern:'〜てはどうか',connection:'動詞て形 ＋ はどうか',meaning:'〜如何？（建議）',example:{ja:'一度、専門家に相談してはどうか。',zh:'不妨找專家商量一次如何？',highlight:'相談してはどうか'},tip:'「〜てはどうか」為較書面的建議；口語用「〜たらどう」，敬語用「〜てはいかがですか」。',quiz:{blank:'はどうか',distractors:['もいいか','ばかりか','からか']}},{id:'n3-g155',pattern:'〜てよかった',connection:'動詞て形 ＋ よかった',meaning:'幸好〜；〜真是太好了',example:{ja:'無事に見つかってよかった。',zh:'幸好平安地找到了。',highlight:'見つかってよかった'},tip:'「〜てよかった」表慶幸；「〜ばよかった」表後悔，是常見混淆點。',quiz:{blank:'よかった',distractors:['ほしかった','しまった','いけない']}},{id:'n3-g156',pattern:'お〜です（尊敬）',connection:'お ＋ 動詞ます形 ＋ です',meaning:'（尊敬語）正在〜；〜了',example:{ja:'社長がお待ちです。',zh:'社長正在等您。',highlight:'お待ちです'},tip:'「お〜です」是尊敬語，主語為對方或上位者；「お〜する／いたす」則是謙讓語。',quiz:{blank:'お待ちです',distractors:['お待ちします','お待ちしています','お待ちいたします']}},{id:'n3-g157',pattern:'お〜いただく',connection:'お ＋ 動詞ます形 ＋ いただく',meaning:'承蒙您〜（謙讓）',example:{ja:'お忙しいところ、お集まりいただきありがとうございます。',zh:'百忙之中承蒙各位前來，非常感謝。',highlight:'お集まりいただき'},tip:'「お〜いただく」為謙讓表現，常與「ありがとうございます」連用；也可說「お〜くださり」。',quiz:{blank:'いただき',distractors:['ください','になり','し']}},{id:'n3-g158',pattern:'〜てみせる',connection:'動詞て形 ＋ みせる',meaning:'做給〜看；一定要〜（決心）',example:{ja:'必ずこの謎を解いてみせる。',zh:'我一定要解開這個謎給你看。',highlight:'解いてみせる'},tip:'「〜てみせる」表強烈決心或示範給人看；「〜てみる」只是嘗試，語氣差很多。',quiz:{blank:'みせる',distractors:['みる','おく','ある']}},{id:'n3-g159',pattern:'〜られる（自發）',connection:'動詞被動形（自發用法）',meaning:'不由得〜；自然地〜',example:{ja:'この写真を見ると、昔のことが思い出される。',zh:'一看到這張照片，就不由得想起往事。',highlight:'思い出される'},tip:'自發用法多接「思い出す、感じる、案じる」等心理動詞，主語常用「が」標示對象。',quiz:{blank:'される',distractors:['させる','す','そう']}},{id:'n3-g160',pattern:'〜られる（受害）',connection:'動詞被動形（受害用法）',meaning:'被〜（受到困擾）',example:{ja:'帰り道で雨に降られた。',zh:'回家路上被雨淋了。',highlight:'雨に降られた'},tip:'受害被動可用自動詞（雨に降られる、子どもに泣かれる），中文常譯為「被〜，害得〜」。',quiz:{blank:'られた',distractors:['った','らせた','りそうだった']}},{id:'n3-g161',pattern:'〜させる（許可）',connection:'動詞使役形（許可、放任）',meaning:'讓〜（允許、放任）',example:{ja:'子どもに好きなだけ遊ばせた。',zh:'讓孩子盡情地玩。',highlight:'遊ばせた'},tip:'使役除「強迫」外還有「允許、放任」的意思；請求許可時說「〜させてください」。',quiz:{blank:'せた',distractors:['れた','なかった','う']}},{id:'n3-g162',pattern:'〜ふりをする',connection:'普通形／名詞の ＋ ふりをする',meaning:'假裝〜',example:{ja:'彼は何も知らないふりをしていた。',zh:'他假裝什麼都不知道。',highlight:'知らないふりをしていた'},tip:'「〜ふりをする」是假裝；「〜たつもり」是自以為已做了，常被拿來比較。',quiz:{blank:'ふり',distractors:['つもり','わけ','ため']}},{id:'n3-g163',pattern:'〜たつもり',connection:'動詞た形 ＋ つもり',meaning:'自以為已經〜；就當作〜',example:{ja:'鍵はかけたつもりだったが、開いていた。',zh:'我以為已經鎖了，門卻是開著的。',highlight:'かけたつもり'},tip:'「た形＋つもり」表自以為已經做了，實際上可能不是；與「辭書形＋つもり（打算）」區分。',quiz:{blank:'つもり',distractors:['ふり','ため','ところ']}},{id:'n3-g164',pattern:'〜つもりはない',connection:'動詞辭書形 ＋ つもりはない',meaning:'沒有〜的打算',example:{ja:'あなたを責めるつもりはない。',zh:'我沒有要責怪你的意思。',highlight:'責めるつもりはない'},tip:'「〜つもりはない」否定自己的意圖；「〜ないつもりだ」則是打算不做，語感略有差異。',quiz:{blank:'つもり',distractors:['ふり','ため','ほど']}},{id:'n3-g165',pattern:'〜ようとしない',connection:'動詞意向形 ＋ としない',meaning:'不肯〜',example:{ja:'容疑者は何も話そうとしない。',zh:'嫌犯什麼都不肯說。',highlight:'話そうとしない'},tip:'「〜ようとしない」用於描述他人不肯做，不用於自己；自己用「〜つもりはない」。',quiz:{blank:'としない',distractors:['とする','としていた','ことはない']}},{id:'n3-g166',pattern:'〜てくる（開始）',connection:'動詞て形 ＋ くる',meaning:'開始〜（出現）',example:{ja:'急に雨が降ってきた。',zh:'突然下起雨來了。',highlight:'降ってきた'},tip:'「〜てくる」可表變化或現象開始出現（雨が降ってきた、お腹がすいてきた）。',quiz:{blank:'きた',distractors:['いった','おいた','あった']}},{id:'n3-g167',pattern:'〜切る',connection:'動詞ます形 ＋ 切る',meaning:'完全〜；〜完',example:{ja:'三日でその本を読み切った。',zh:'三天就把那本書讀完了。',highlight:'読み切った'},tip:'「〜切る」表徹底做完；否定形「〜きれない」表無法全部做完。',quiz:{blank:'切った',distractors:['かけた','始めた','忘れた']}},{id:'n3-g168',pattern:'〜きれない',connection:'動詞ます形 ＋ きれない',meaning:'無法完全〜；〜不完',example:{ja:'一人では食べきれないほどの料理だ。',zh:'是一個人吃不完的大量料理。',highlight:'食べきれない'},tip:'「〜きれない」表數量太多做不完，常說「数えきれない」「食べきれない」。',quiz:{blank:'きれない',distractors:['たくない','すぎない','かけない']}},{id:'n3-g169',pattern:'〜かける',connection:'動詞ます形 ＋ かける',meaning:'〜到一半；差點〜',example:{ja:'彼は何か言いかけて、黙ってしまった。',zh:'他話說到一半就沉默了。',highlight:'言いかけて'},tip:'「〜かける」表動作做到一半或快要發生；名詞形「〜かけの」修飾名詞。',quiz:{blank:'かけて',distractors:['切って','合って','込んで']}},{id:'n3-g170',pattern:'〜かけの',connection:'動詞ます形 ＋ かけの ＋ 名詞',meaning:'〜到一半的',example:{ja:'机の上に飲みかけのコーヒーが残っていた。',zh:'桌上留著喝到一半的咖啡。',highlight:'飲みかけの'},tip:'「〜かけの＋名詞」＝做到一半的；「〜たての」＝剛做好的，兩者常對比。',quiz:{blank:'かけの',distractors:['たての','きれない','慣れた']}},{id:'n3-g171',pattern:'〜合う',connection:'動詞ます形 ＋ 合う',meaning:'互相〜',example:{ja:'困ったときは、みんなで助け合いましょう。',zh:'遇到困難時，大家互相幫助吧。',highlight:'助け合い'},tip:'「〜合う」表雙方互相做某事，主語為複數；如「話し合う」「助け合う」。',quiz:{blank:'合い',distractors:['出し','かけ','込み']}},{id:'n3-g172',pattern:'〜慣れる',connection:'動詞ます形 ＋ 慣れる',meaning:'〜慣了；習慣〜',example:{ja:'履き慣れた靴で出かける。',zh:'穿著穿慣的鞋出門。',highlight:'履き慣れた'},tip:'「〜慣れる」表做習慣了，常以「〜慣れた＋名詞」修飾（使い慣れた、住み慣れた）。',quiz:{blank:'慣れた',distractors:['忘れた','かけた','切った']}},{id:'n3-g173',pattern:'〜忘れる',connection:'動詞ます形 ＋ 忘れる',meaning:'忘了〜',example:{ja:'手紙に名前を書き忘れた。',zh:'信上忘了寫名字。',highlight:'書き忘れた'},tip:'「〜忘れる」表忘了做某事；與單獨的「忘れる（忘記某物）」用法不同。',quiz:{blank:'忘れた',distractors:['慣れた','切った','込んだ']}},{id:'n3-g174',pattern:'〜込む',connection:'動詞ます形 ＋ 込む',meaning:'〜進去；深入〜',example:{ja:'犯人は裏口から忍び込んだらしい。',zh:'犯人似乎是從後門潛入的。',highlight:'忍び込んだ'},tip:'「〜込む」表進入內部或深入、持續（飛び込む、考え込む）。',quiz:{blank:'込んだ',distractors:['忘れた','合った','慣れた']}},{id:'n3-g175',pattern:'〜たて',connection:'動詞ます形 ＋ たて',meaning:'剛〜好的',example:{ja:'焼きたてのパンはおいしい。',zh:'剛烤好的麵包很好吃。',highlight:'焼きたて'},tip:'「〜たて」表剛完成、新鮮，限接部分動詞（焼きたて、できたて、塗りたて）。',quiz:{blank:'たて',distractors:['かけ','すぎ','ながら']}},{id:'n3-g176',pattern:'〜だらけ',connection:'名詞 ＋ だらけ',meaning:'滿是〜；全是〜',example:{ja:'犯人の靴は泥だらけだった。',zh:'犯人的鞋子滿是泥巴。',highlight:'泥だらけ'},tip:'「〜だらけ」帶負面語感（泥、傷、間違い）；「〜でいっぱい」則中性。',quiz:{blank:'だらけ',distractors:['ぶり','ごと','どおり']}},{id:'n3-g177',pattern:'〜ぶり',connection:'時間名詞 ＋ ぶり',meaning:'相隔〜（時間）之久',example:{ja:'五年ぶりに故郷に帰った。',zh:'相隔五年回到了故鄉。',highlight:'五年ぶり'},tip:'「時間＋ぶり」表隔了多久再次發生；「〜ごとに」表每隔多久，意思不同。',quiz:{blank:'ぶり',distractors:['ごと','だらけ','まで']}},{id:'n3-g178',pattern:'〜ごと（連同）',connection:'名詞 ＋ ごと',meaning:'連同〜一起',example:{ja:'りんごを皮ごと食べる。',zh:'蘋果連皮一起吃。',highlight:'皮ごと'},tip:'名詞＋ごと＝連同〜一起；與「〜ごとに（每〜）」不同。',quiz:{blank:'ごと',distractors:['だらけ','ぶり','どおり']}},{id:'n3-g179',pattern:'〜み',connection:'い形容詞／な形容詞語幹 ＋ み',meaning:'〜感；〜之處（名詞化）',example:{ja:'この絵には温かみがある。',zh:'這幅畫有一種溫暖感。',highlight:'温かみ'},tip:'「〜み」表可感受到的性質，只接部分形容詞（温かみ、重み、楽しみ）；「〜さ」表程度。',quiz:{blank:'み',distractors:['げ','そう','く']}},{id:'n3-g180',pattern:'〜的',connection:'名詞 ＋ 的',meaning:'〜的；〜性的',example:{ja:'彼の意見はとても現実的だ。',zh:'他的意見非常務實。',highlight:'現実的'},tip:'「〜的」使名詞形容詞化，接な形容詞用法（現実的な考え、現実的だ）。',quiz:{blank:'的',distractors:['化','性','製']}},{id:'n3-g181',pattern:'〜化',connection:'名詞 ＋ 化',meaning:'〜化',example:{ja:'少子化が大きな問題になっている。',zh:'少子化成了一大問題。',highlight:'少子化'},tip:'「〜化」表變成某狀態，可接「する」作動詞（国際化する、少子化が進む）。',quiz:{blank:'化',distractors:['的','性','風']}},{id:'n3-g182',pattern:'〜性',connection:'名詞 ＋ 性',meaning:'〜性',example:{ja:'この薬の安全性はまだ確認されていない。',zh:'這種藥的安全性尚未確認。',highlight:'安全性'},tip:'「〜性」表性質或可能性（安全性、可能性、必要性），本身為名詞。',quiz:{blank:'性',distractors:['的','化','製']}},{id:'n3-g183',pattern:'〜製',connection:'名詞 ＋ 製',meaning:'〜製造的',example:{ja:'このナイフはドイツ製だ。',zh:'這把刀是德國製的。',highlight:'ドイツ製'},tip:'「國名／材料＋製」表產地或材質（日本製、プラスチック製）。',quiz:{blank:'製',distractors:['的','化','風']}},{id:'n3-g184',pattern:'〜風（ふう）',connection:'名詞 ＋ 風',meaning:'〜風格；〜樣式',example:{ja:'駅の近くに和風の旅館がある。',zh:'車站附近有一間日式旅館。',highlight:'和風'},tip:'「〜風」讀「ふう」，表風格、樣式（和風、洋風、学生風）。',quiz:{blank:'風',distractors:['的','性','化']}},{id:'n3-g185',pattern:'〜目（序數）',connection:'數量詞 ＋ 目',meaning:'第〜',example:{ja:'これで三件目の事件だ。',zh:'這已經是第三起案件了。',highlight:'三件目'},tip:'數量詞＋目表順序（三件目、二回目），讀「め」；數量詞本身只表數量。',quiz:{blank:'目',distractors:['ずつ','ごと','ほど']}},{id:'n3-g186',pattern:'〜なしで',connection:'名詞 ＋ なしで',meaning:'沒有〜；不帶〜',example:{ja:'辞書なしでこの本を読むのは難しい。',zh:'不查字典很難讀這本書。',highlight:'辞書なしで'},tip:'「〜なしで」表在缺少某物的狀態下做；「〜抜きで」多指刻意去掉原本該有的東西。',quiz:{blank:'なしで',distractors:['だらけで','として','ごとに']}},{id:'n3-g187',pattern:'〜抜きで',connection:'名詞 ＋ 抜きで',meaning:'去掉〜；不加〜',example:{ja:'今日は冗談抜きで話そう。',zh:'今天就不開玩笑，認真談吧。',highlight:'冗談抜きで'},tip:'「冗談抜きで」為慣用語，意為「說真的」；「〜抜き」強調刻意省去。',quiz:{blank:'抜きで',distractors:['だらけで','ばかりで','として']}},{id:'n3-g188',pattern:'〜まま（に）',connection:'動詞辭書形／被動形 ＋ まま（に）',meaning:'任憑〜；隨著〜',example:{ja:'足の向くままに町を歩いた。',zh:'信步在街上隨意走著。',highlight:'向くままに'},tip:'「〜ままに」表任憑、順隨（言われるままに、気の向くままに），與表維持狀態的「〜まま」不同。',quiz:{blank:'ままに',distractors:['うちに','たびに','ために']}},{id:'n3-g189',pattern:'〜とは（定義）',connection:'名詞 ＋ とは',meaning:'所謂〜是指',example:{ja:'アリバイとは、現場不在証明のことだ。',zh:'所謂不在場證明，是指證明當時不在現場。',highlight:'アリバイとは'},tip:'定義句型「AとはBのことだ」，口語說「Aっていうのは」。',quiz:{blank:'とは',distractors:['こそ','さえ','ほど']}},{id:'n3-g190',pattern:'〜とは（驚訝）',connection:'普通形 ＋ とは',meaning:'竟然〜',example:{ja:'こんな簡単な問題が解けないとは、情けない。',zh:'連這麼簡單的問題都解不開，真是丟臉。',highlight:'解けないとは'},tip:'句尾「〜とは」表驚訝、感嘆，與「〜なんて」相近但較書面。',quiz:{blank:'とは',distractors:['こそ','さえ','のに']}},{id:'n3-g191',pattern:'〜とは思わなかった',connection:'普通形 ＋ とは思わなかった',meaning:'沒想到〜',example:{ja:'こんな所で君に会うとは思わなかった。',zh:'沒想到會在這種地方遇見你。',highlight:'会うとは思わなかった'},tip:'「〜とは思わなかった」＝「〜なんて思わなかった」，常與「まさか」連用。',quiz:{blank:'とは',distractors:['ので','ほど','しか']}},{id:'n3-g192',pattern:'〜というと',connection:'名詞 ＋ というと',meaning:'說到〜；提到〜',example:{ja:'京都というと、やはりお寺だろう。',zh:'說到京都，還是會想到寺廟吧。',highlight:'京都というと'},tip:'「〜というと」用於提起話題或確認對方的話；與「〜といえば」常可互換。',quiz:{blank:'というと',distractors:['にとって','によって','に対して']}},{id:'n3-g193',pattern:'〜といえば',connection:'名詞 ＋ といえば',meaning:'說到〜（聯想）',example:{ja:'夏といえば、花火だ。',zh:'說到夏天就想到煙火。',highlight:'夏といえば'},tip:'「〜といえば」表由話題聯想到代表性事物，也可說「〜といったら」。',quiz:{blank:'といえば',distractors:['にとって','によって','に対して']}},{id:'n3-g194',pattern:'〜というのは',connection:'名詞 ＋ というのは',meaning:'所謂〜；〜這件事是',example:{ja:'密室というのは、だれも出入りできない部屋のことだ。',zh:'所謂密室，是指沒人能進出的房間。',highlight:'密室というのは'},tip:'「〜というのは〜のことだ／〜という意味だ」為定義、說明句型。',quiz:{blank:'というのは',distractors:['といっても','というより','としても']}},{id:'n3-g195',pattern:'〜という（名稱）',connection:'名詞 ＋ という ＋ 名詞',meaning:'叫做〜的',example:{ja:'これは「黒猫」という喫茶店です。',zh:'這是一家叫「黑貓」的咖啡廳。',highlight:'「黒猫」という'},tip:'「〜という＋名詞」用於介紹名稱；口語為「〜っていう」。',quiz:{blank:'という',distractors:['のような','として','による']}},{id:'n3-g196',pattern:'〜というより',connection:'普通形／名詞 ＋ というより',meaning:'與其說〜不如說〜',example:{ja:'彼は探偵というより、学者のようだ。',zh:'與其說他是偵探，不如說像學者。',highlight:'探偵というより'},tip:'「AというよりB」表與其說A不如說B，後句常加「むしろ」。',quiz:{blank:'というより',distractors:['というと','といえば','によって']}},{id:'n3-g197',pattern:'〜といっても',connection:'普通形／名詞 ＋ といっても',meaning:'雖說〜但是〜',example:{ja:'料理ができるといっても、簡単なものだけだ。',zh:'雖說會做菜，也只會做簡單的。',highlight:'できるといっても'},tip:'「〜といっても」先承認再修正，表實際程度不如想像；「からといって」則接否定結論。',quiz:{blank:'といっても',distractors:['というより','というのは','からといって']}},{id:'n3-g198',pattern:'〜ということだ（結論）',connection:'普通形 ＋ ということだ',meaning:'也就是說〜',example:{ja:'鍵が内側からかかっていた。つまり、犯人はまだ中にいたということだ。',zh:'鑰匙是從內側鎖上的，也就是說犯人當時還在裡面。',highlight:'いたということだ'},tip:'結論用法常與「つまり」「要するに」呼應；傳聞用法則與「〜そうだ」相近。',quiz:{blank:'ということだ',distractors:['というより','ことがある','わけがない']}},{id:'n3-g199',pattern:'〜とか（傳聞）',connection:'普通形 ＋ とか',meaning:'聽說〜好像',example:{ja:'お隣の息子さん、来月結婚するとか。',zh:'聽說隔壁家的兒子下個月要結婚。',highlight:'結婚するとか'},tip:'句尾「〜とか」表不確定的傳聞，比「〜そうだ」語氣更模糊；與列舉的「〜とか〜とか」不同。',quiz:{blank:'とか',distractors:['っけ','ので','ほど']}},{id:'n3-g200',pattern:'〜と言われている',connection:'普通形 ＋ と言われている',meaning:'一般認為〜；據說〜',example:{ja:'この寺は千年前に建てられたと言われている。',zh:'據說這座寺廟建於千年前。',highlight:'建てられたと言われている'},tip:'表一般說法或傳說，多用於新聞、說明文；個人傳聞則用「〜そうだ」。',quiz:{blank:'と言われている',distractors:['ようにしている','ばかりだ','ことにしている']}},{id:'n3-g201',pattern:'〜と考えられる',connection:'普通形 ＋ と考えられる',meaning:'可以認為〜；推測是〜',example:{ja:'犯人は被害者の知り合いだと考えられる。',zh:'推測犯人是被害者的熟人。',highlight:'知り合いだと考えられる'},tip:'「〜と考えられる」為客觀推論的書面語，常見於報告、新聞。',quiz:{blank:'と考えられる',distractors:['に考えられる','を考えられる','と考えさせる']}},{id:'n3-g202',pattern:'まるで〜ようだ',connection:'まるで ＋ 普通形／名詞の ＋ ようだ',meaning:'簡直就像〜一樣',example:{ja:'部屋はまるで嵐が去った後のようだった。',zh:'房間簡直像暴風雨過後一樣。',highlight:'まるで嵐が去った後のようだった'},tip:'「まるで」須與「〜ようだ／みたいだ」呼應，不與「〜らしい」「〜そうだ（傳聞）」連用。',quiz:{blank:'ようだった',distractors:['らしかった','そうだった','はずだった']}},{id:'n3-g203',pattern:'どうやら〜らしい',connection:'どうやら ＋ 普通形 ＋ らしい',meaning:'看來好像〜',example:{ja:'どうやら犯人は二人いるらしい。',zh:'看來犯人好像有兩個人。',highlight:'どうやら犯人は二人いるらしい'},tip:'「どうやら」與推測的「らしい／ようだ／みたいだ」呼應，表根據情況的推斷。',quiz:{blank:'らしい',distractors:['べきだ','つもりだ','ことだ']}},{id:'n3-g204',pattern:'いまにも〜そうだ',connection:'いまにも ＋ 動詞ます形 ＋ そうだ',meaning:'眼看就要〜',example:{ja:'空が暗くて、いまにも雨が降りそうだ。',zh:'天空很暗，眼看就要下雨了。',highlight:'いまにも雨が降りそうだ'},tip:'「いまにも」只與樣態「ます形＋そうだ」呼應，表眼看就要發生。',quiz:{blank:'そうだ',distractors:['ようだ','らしい','たがる']}},{id:'n3-g205',pattern:'せっかく〜のに',connection:'せっかく ＋ 普通形 ＋ のに',meaning:'特地〜卻〜；難得〜卻',example:{ja:'せっかく来たのに、店は閉まっていた。',zh:'特地來了，店卻關門了。',highlight:'せっかく来たのに'},tip:'「せっかく〜のに」表惋惜；「せっかく〜から」則表既然難得就好好利用，後接意志或建議。',quiz:{blank:'のに',distractors:['ので','から','ために']}},{id:'n3-g206',pattern:'決して〜ない',connection:'決して ＋ 動詞ない形',meaning:'絕對不〜',example:{ja:'このことは決してだれにも言わない。',zh:'這件事我絕對不會告訴任何人。',highlight:'決してだれにも言わない'},tip:'「決して」必須與否定呼應，表強烈否定或決心；不能用於肯定句。',quiz:{blank:'決して',distractors:['ぜひ','まるで','せっかく']}},{id:'n3-g207',pattern:'めったに〜ない',connection:'めったに ＋ 動詞ない形',meaning:'很少〜；幾乎不〜',example:{ja:'この辺りでは事件はめったに起きない。',zh:'這一帶很少發生案件。',highlight:'めったに起きない'},tip:'「めったに〜ない」表頻率極低；肯定句的「めったにない」則表罕見。',quiz:{blank:'めったに',distractors:['ぜひ','まるで','いまにも']}},{id:'n3-g208',pattern:'べつに〜ない',connection:'べつに ＋ 動詞ない形／形容詞否定',meaning:'並不特別〜',example:{ja:'べつに怒っているわけじゃない。',zh:'我並沒有特別生氣。',highlight:'べつに怒っているわけじゃない'},tip:'「べつに〜ない」表並不特別；單獨回答「別に。」表冷淡的「沒什麼」。',quiz:{blank:'べつに',distractors:['ぜひ','いまにも','せっかく']}},{id:'n3-g209',pattern:'いったい〜か',connection:'いったい ＋ 疑問詞 ＋ 普通形 ＋ か',meaning:'到底〜呢？',example:{ja:'いったいだれがこんなことをしたのか。',zh:'到底是誰做了這種事？',highlight:'いったいだれが'},tip:'「いったい」常與疑問詞連用，表強烈疑問、不滿，句尾常為「〜のか／〜のだろう」。',quiz:{blank:'いったい',distractors:['ぜひ','決して','まるで']}},{id:'n3-g210',pattern:'もしかしたら〜かもしれない',connection:'もしかしたら ＋ 普通形 ＋ かもしれない',meaning:'說不定〜',example:{ja:'もしかしたら、彼は何か知っているかもしれない。',zh:'說不定他知道些什麼。',highlight:'もしかしたら'},tip:'「もしかしたら／もしかすると」與「かもしれない」呼應，表可能性低的推測。',quiz:{blank:'かもしれない',distractors:['はずがない','ことにする','ばかりだ']}},{id:'n3-g211',pattern:'必ずしも〜とは限らない',connection:'必ずしも ＋ 普通形 ＋ とは限らない',meaning:'未必〜',example:{ja:'高い物が必ずしもいい物とは限らない。',zh:'貴的東西未必就是好東西。',highlight:'必ずしも'},tip:'「必ずしも」必須搭配部分否定「〜とは限らない／〜わけではない」。',quiz:{blank:'とは限らない',distractors:['に違いない','に決まっている','ことだ']}},{id:'n3-g212',pattern:'〜を〜として',connection:'名詞 ＋ を ＋ 名詞 ＋ として',meaning:'把〜作為〜',example:{ja:'この部屋を事務所として使っている。',zh:'把這個房間當作辦公室使用。',highlight:'事務所として'},tip:'「AをBとして」＝把A當作B；「AをBにする」語意相近但較口語。',quiz:{blank:'として',distractors:['について','によって','にとって']}},{id:'n3-g213',pattern:'〜によって（被動行為者）',connection:'名詞 ＋ によって',meaning:'由〜（被動句的行為者）',example:{ja:'この小説は有名な作家によって書かれた。',zh:'這本小說是由知名作家寫的。',highlight:'作家によって'},tip:'被動句中表創作者、發明者、發現者時用「によって」，一般行為者用「に」。',quiz:{blank:'によって',distractors:['について','にとって','に対して']}},{id:'n3-g214',pattern:'〜から見ると',connection:'名詞 ＋ から見ると',meaning:'從〜來看',example:{ja:'子どもから見ると、大人の世界は不思議だ。',zh:'從孩子的角度來看，大人的世界很不可思議。',highlight:'子どもから見ると'},tip:'表從某人的立場或觀點判斷，可換成「〜から見れば／〜から見たら」。',quiz:{blank:'から見ると',distractors:['について','によって','に対して']}},{id:'n3-g215',pattern:'〜より（起點）',connection:'名詞 ＋ より',meaning:'從〜（書面語）',example:{ja:'会議は午後二時より始まります。',zh:'會議從下午兩點開始。',highlight:'午後二時より'},tip:'表起點的「より」為書面、正式用法（通知、廣播），口語用「から」。',quiz:{blank:'より',distractors:['まで','ほど','だけ']}},{id:'n3-g216',pattern:'〜うちは',connection:'動詞ている形／形容詞／名詞の ＋ うちは',meaning:'在〜期間；趁〜的時候',example:{ja:'若いうちは、いろいろな経験をしたほうがいい。',zh:'趁年輕的時候，最好多累積各種經驗。',highlight:'若いうちは'},tip:'「〜うちは」強調在該狀態持續期間（之後就不同了）；「〜うちに」表趁著。',quiz:{blank:'うちは',distractors:['とたんに','たびに','最中に']}},{id:'n3-g217',pattern:'〜わけ（理由）',connection:'普通形 ＋ わけ',meaning:'原因；理由（〜的緣故）',example:{ja:'遅れたわけを話してください。',zh:'請說明遲到的理由。',highlight:'遅れたわけ'},tip:'名詞「わけ」表理由、原因，可說「わけを話す／聞く」；與句尾「〜わけだ」不同。',quiz:{blank:'わけ',distractors:['はず','つもり','ふり']}},{id:'n3-g218',pattern:'〜ようか（猶豫）',connection:'動詞意向形 ＋ か（＋ 迷う／考える）',meaning:'要不要〜呢（猶豫）',example:{ja:'警察に言おうか、黙っていようか迷っている。',zh:'正在猶豫要告訴警察還是保持沉默。',highlight:'言おうか'},tip:'「〜ようか〜ようか迷う」表在兩個選項間猶豫；單獨「〜ようか」也可表提議。',quiz:{blank:'おうか',distractors:['えるか','ったか','わせるか']}},{id:'n3-g219',pattern:'〜にしたら',connection:'名詞 ＋ にしたら',meaning:'站在〜的立場來看',example:{ja:'母親にしたら、心配するのは当然だ。',zh:'站在母親的立場，擔心是理所當然的。',highlight:'母親にしたら'},tip:'「〜にしたら」用於體諒他人的立場或心情，可換成「〜にしてみれば」，不用於自己。',quiz:{blank:'にしたら',distractors:['によって','について','に対して']}}]},1246,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"N3_READING",{enumerable:!0,get:function(){return n}});const n=[{id:"n3-r01",title:"朝の三十分",titleZh:"早晨的三十分鐘",topic:"生活",paragraphs:[{ja:"去年の春から、私はいつもより三十分早く起きるようにしている。きっかけは、会社に遅れそうになって駅まで走った日のことだ。駅に着いたときには息が切れて、一日が始まる前にもう疲れていた。電車の中で汗をかきながら、「毎朝こんなに急いでいて、本当にいいのだろうか」と考えた。",zh:"從去年春天開始，我都盡量比平常早三十分鐘起床。契機是某天我差點上班遲到，一路跑到車站。到車站時已經上氣不接下氣，一天還沒開始就累壞了。我在電車裡一邊流汗一邊想：「每天早上都這麼匆忙，真的好嗎？」"},{ja:"最初の一週間は本当につらかった。目覚まし時計が鳴っても、なかなか布団から出られない。しかし、夜は早く寝るように気をつけると、少しずつ体が慣れてきた。今では、目覚まし時計が鳴る前に目が覚めることもある。",zh:"第一個星期真的很痛苦。就算鬧鐘響了，也很難從被窩裡爬出來。不過，晚上注意早點睡之後，身體慢慢就習慣了。現在有時候甚至在鬧鐘響之前就醒來了。"},{ja:"増えた三十分で、私は特別なことをしているわけではない。コーヒーをゆっくり飲んだり、窓の外を眺めたり、日記を書いたりするだけだ。それでも、一日の始まりに自分のための時間があると、気持ちに余裕が生まれる。仕事で嫌なことがあっても、以前ほどいらいらしなくなった。",zh:"多出來的三十分鐘，我並沒有做什麼特別的事，只是慢慢喝杯咖啡、望望窗外、寫寫日記而已。即使如此，在一天的開始擁有屬於自己的時間，心情就會變得從容。就算工作上遇到討厭的事，也不再像以前那樣煩躁了。"},{ja:"もちろん、早起きがすべての人に合うとは限らない。夜のほうが集中できる人もいるだろう。大切なのは、自分に合った生活のリズムを見つけることだと思う。私にとって、それが朝の三十分だったのだ。",zh:"當然，早起不一定適合每個人。應該也有人在晚上比較能專心吧。我認為重要的是找到適合自己的生活節奏。對我來說，那就是早晨的三十分鐘。"}],vocab:[{word:"きっかけ",reading:"きっかけ",meaning:"契機、開端"},{word:"慣れる",reading:"なれる",meaning:"習慣、適應"},{word:"眺める",reading:"ながめる",meaning:"眺望、凝視"},{word:"余裕",reading:"よゆう",meaning:"從容、餘裕"},{word:"集中",reading:"しゅうちゅう",meaning:"專心、集中"},{word:"限る",reading:"かぎる",meaning:"限於（～とは限らない：不一定）"}],questions:[{question:"筆者が早起きを始めたきっかけは何か。",questionZh:"作者開始早起的契機是什麼？",options:["会社に遅れそうになって駅まで走ったこと","医者に早く起きるように言われたこと","友達に朝の散歩に誘われたこと","新しい目覚まし時計を買ったこと"]},{question:"筆者の考えに合うものはどれか。",questionZh:"下列哪一項符合作者的想法？",options:["自分に合った生活のリズムを見つけることが大切だ","すべての人が早起きをするべきだ","夜に仕事をするのはよくない","朝の時間は特別なことに使うべきだ"]}]},{id:"n3-r02",title:"ごみの出し方が変わります",titleZh:"垃圾丟法即將變更",topic:"生活",paragraphs:[{ja:"さくら台マンションにお住まいの皆様へ。いつもごみ置き場をきれいに使っていただき、ありがとうございます。来月一日から市のルールが変わるため、このマンションのごみの出し方も一部変更になります。以下の内容をよくお読みください。",zh:"致櫻台公寓的各位住戶：感謝大家平時保持垃圾放置處的整潔。由於下個月一日起市政府的規定將有所改變，本公寓的垃圾丟法也將部分變更。請仔細閱讀以下內容。"},{ja:"まず、プラスチックごみの日が、これまでの水曜日から金曜日に変わります。また、ペットボトルはプラスチックごみとは別に集めることになりました。ペットボトルを出すときは、キャップとラベルを外し、中を軽く洗ってから、専用の青い箱に入れてください。",zh:"首先，塑膠垃圾的收集日將從原本的星期三改為星期五。另外，寶特瓶將與塑膠垃圾分開收集。丟寶特瓶時，請拿掉瓶蓋和標籤，把裡面稍微沖洗後，放進專用的藍色箱子。"},{ja:"次に、ごみを出す時間についてです。最近、前の日の夜にごみを出す方がいらっしゃいますが、カラスに袋を破られて、ごみが散らかることが増えています。ごみは必ず当日の朝八時までに出してください。夜に出すことはご遠慮ください。",zh:"接下來是關於丟垃圾的時間。最近有住戶在前一天晚上就把垃圾拿出來，結果袋子被烏鴉啄破、垃圾散落一地的情況越來越多。請務必在收集當天早上八點前丟垃圾，並請避免在晚上丟出。"},{ja:"新しいルールについてわからないことがあれば、管理人室までお気軽にお問い合わせください。管理人は月曜日から土曜日の午前九時から午後五時までおります。住みやすいマンションにするために、皆様のご協力をよろしくお願いいたします。さくら台マンション管理組合",zh:"若對新規定有任何不清楚的地方，歡迎隨時到管理員室詢問。管理員在星期一到星期六的上午九點到下午五點都在。為了讓公寓成為更舒適的住處，敬請各位配合。櫻台公寓管理委員會"}],vocab:[{word:"一部",reading:"いちぶ",meaning:"一部分"},{word:"変更",reading:"へんこう",meaning:"變更"},{word:"外す",reading:"はずす",meaning:"取下、拿掉"},{word:"専用",reading:"せんよう",meaning:"專用"},{word:"散らかる",reading:"ちらかる",meaning:"散亂、凌亂"},{word:"遠慮",reading:"えんりょ",meaning:"避免、謝絕；客氣"},{word:"協力",reading:"きょうりょく",meaning:"合作、配合"}],questions:[{question:"来月から、ペットボトルはどう出せばよいか。",questionZh:"從下個月起，寶特瓶應該怎麼丟？",options:["キャップとラベルを外し、中を洗ってから青い箱に入れる","プラスチックごみと一緒に水曜日に出す","キャップをつけたまま金曜日の袋に入れる","前の日の夜に管理人室に持っていく"]},{question:"このお知らせによると、してはいけないことはどれか。",questionZh:"根據這則通知，哪一項是不可以做的？",options:["前の日の夜にごみを出すこと","朝七時にごみを出すこと","管理人に質問すること","金曜日にプラスチックごみを出すこと"]}]},{id:"n3-r03",title:"風呂敷のよさ",titleZh:"包袱巾的好處",topic:"文化",paragraphs:[{ja:"皆さんは「風呂敷」を使ったことがありますか。風呂敷は、物を包んだり運んだりするための四角い布です。昔、お風呂に行くときに服を包んだり、床に敷いたりしていたので、この名前がついたと言われています。",zh:"大家用過「風呂敷」（包袱巾）嗎？包袱巾是用來包裹或搬運物品的方形布。據說以前人們去澡堂時會用它包衣服，或是鋪在地上，因此才有了這個名字。"},{ja:"今では紙袋やレジ袋が広く使われるようになり、風呂敷を持っている若い人は少なくなりました。しかし、最近、風呂敷がもう一度注目されています。理由の一つは、何度でも使えるので、ごみを減らすことができるからです。",zh:"如今紙袋和塑膠袋被廣泛使用，擁有包袱巾的年輕人變少了。不過，最近包袱巾再次受到關注。原因之一是它可以重複使用很多次，能夠減少垃圾。"},{ja:"風呂敷のいいところは、包む物の形を選ばないことです。箱はもちろん、瓶や本、丸い果物でも、結び方を工夫すれば上手に包めます。使わないときは小さくたたんで、かばんに入れておけます。また、きれいな柄の風呂敷は、テーブルにかけたり、壁に飾ったりすることもできます。",zh:"包袱巾的優點是不挑所包物品的形狀。箱子就不用說了，就連瓶子、書或圓形的水果，只要在綁法上下點工夫都能包得很好。不用時可以摺小放進包包裡。另外，花樣漂亮的包袱巾也可以鋪在桌上或掛在牆上當裝飾。"},{ja:"私も去年、祖母から古い風呂敷をもらいました。初めは結び方がわからず、何度も失敗しましたが、今では買い物のときに欠かせない物になっています。昔の人の知恵は、今の生活にも十分役に立つのだと感じています。",zh:"我去年也從祖母那裡得到了一條舊包袱巾。一開始不知道怎麼綁，失敗了好多次，但現在它已經成為我購物時不可或缺的東西。我深深感受到，古人的智慧在現代生活中也非常有用。"}],vocab:[{word:"包む",reading:"つつむ",meaning:"包、包裹"},{word:"注目",reading:"ちゅうもく",meaning:"注目、關注"},{word:"減らす",reading:"へらす",meaning:"減少"},{word:"工夫",reading:"くふう",meaning:"下工夫、設法"},{word:"飾る",reading:"かざる",meaning:"裝飾"},{word:"欠かせない",reading:"かかせない",meaning:"不可或缺的"},{word:"知恵",reading:"ちえ",meaning:"智慧"}],questions:[{question:"風呂敷が最近また注目されている理由として、文章で挙げられているのはどれか。",questionZh:"文章中提到包袱巾最近再度受到關注的理由是哪一個？",options:["何度でも使えて、ごみを減らせるから","紙袋より値段が安いから","若い人の間で服として人気があるから","お風呂屋さんで必要になったから"]},{question:"風呂敷について正しいものはどれか。",questionZh:"關於包袱巾，哪一項是正確的？",options:["結び方を工夫すれば、丸い物も包める","四角い箱しか包めない","使わないときは大きくてじゃまになる","柄のある風呂敷は飾ることができない"]},{question:"筆者は今、風呂敷をどう使っているか。",questionZh:"作者現在如何使用包袱巾？",options:["買い物のときに使っている","壁に飾っているだけだ","祖母に返した","友達にプレゼントした"]}]},{id:"n3-r04",title:"夏祭りの太鼓",titleZh:"夏日祭典的太鼓",topic:"文化",paragraphs:[{ja:"僕が生まれた町では、毎年八月に小さな夏祭りがある。祭りの夜には、町の子どもたちが大きな太鼓をたたきながら、神社までの道を歩く。小学生のころの僕は、その太鼓の音を聞くと、胸がどきどきしたものだ。",zh:"在我出生的小鎮，每年八月都會舉行小小的夏日祭典。祭典當晚，鎮上的孩子們會一邊敲著大太鼓，一邊走向神社。小學時的我，一聽到那太鼓聲，心就會怦怦跳。"},{ja:"大学に入って東京で一人暮らしを始めてから、祭りのことはほとんど思い出さなくなった。ところが、今年の夏、母から電話がかかってきた。「太鼓をたたく子どもが足りなくて、今年で祭りをやめるかもしれない」と言うのだ。町では若い人が減り、子どもの数も年々少なくなっているらしい。",zh:"上大學後在東京開始一個人生活，我幾乎不再想起祭典的事。然而今年夏天，母親打了電話來，說：「敲太鼓的孩子不夠，祭典可能今年就要停辦了。」聽說鎮上的年輕人變少，孩子的人數也一年比一年少。"},{ja:"僕は迷ったが、休みを取って町に帰ることにした。そして、子どもたちと一緒に太鼓の練習をした。久しぶりにたたいた太鼓は思ったより重く、腕がすぐに痛くなった。それでも、子どもたちが真剣な顔で練習する様子を見ていると、昔の自分を見ているような気がした。",zh:"我猶豫了一下，還是決定請假回鎮上，和孩子們一起練習太鼓。久違地敲起太鼓，比想像中沉重，手臂很快就痠痛了。即使如此，看著孩子們一臉認真練習的樣子，我覺得好像看到了從前的自己。"},{ja:"祭りの夜、太鼓の音は町中に響いた。見に来たお年寄りの中には、涙を流している人もいた。祭りが終わったあと、一人の男の子が「来年も来てくれる？」と聞いてきた。僕は少し考えてから、「もちろん」と答えた。",zh:"祭典當晚，太鼓聲響徹整個小鎮。來觀看的老人家之中，也有人流下了眼淚。祭典結束後，一個男孩問我：「明年也會來嗎？」我想了一下，回答：「當然。」"}],vocab:[{word:"一人暮らし",reading:"ひとりぐらし",meaning:"獨自生活"},{word:"年々",reading:"ねんねん",meaning:"逐年、一年比一年"},{word:"迷う",reading:"まよう",meaning:"猶豫、迷惘"},{word:"真剣",reading:"しんけん",meaning:"認真"},{word:"様子",reading:"ようす",meaning:"樣子、情況"},{word:"響く",reading:"ひびく",meaning:"響徹、迴響"},{word:"涙",reading:"なみだ",meaning:"眼淚"}],questions:[{question:"母が電話をかけてきたのはなぜか。",questionZh:"母親為什麼打電話來？",options:["子どもが足りず、祭りがなくなるかもしれないと伝えるため","早く東京から帰ってきてほしかったため","太鼓が壊れたことを知らせるため","東京に遊びに行きたかったため"]},{question:"練習のとき、「僕」はどう感じたか。",questionZh:"練習時，「我」有什麼感覺？",options:["子どもたちを見て、昔の自分を見ているようだと感じた","太鼓が軽くて簡単だと感じた","練習がつまらなくて帰りたくなった","子どもたちが真剣ではないので腹が立った"]}]},{id:"n3-r05",title:"町の本屋を守るには",titleZh:"如何守護街上的書店",topic:"社會",paragraphs:[{ja:"最近、町から小さな本屋が次々と消えている。インターネットで本を注文すれば、次の日には家に届く。電子書籍なら、スマホ一つで何百冊も持ち歩ける。便利な時代になったのだから、本屋が減るのは仕方がないことなのかもしれない。",zh:"最近，小書店一間接一間地從街上消失。在網路上訂書，隔天就會送到家。若是電子書，一支手機就能帶著好幾百本書走。時代變得這麼方便，書店減少或許也是無可奈何的事。"},{ja:"しかし、本屋には、ネットにはない良さがあると私は思う。それは、探していなかった本に出会えることだ。目的の本を探して棚の間を歩いていると、ふと気になる表紙が目に入る。手に取って数ページ読んでみたら面白くて、結局その本も買ってしまう。そんな経験をした人は多いだろう。",zh:"但是，我認為書店有網路所沒有的優點，那就是能遇見原本沒在找的書。在書架間尋找要買的書時，不經意間會看到吸引自己的封面。拿起來讀了幾頁覺得很有趣，結果連那本也買了。應該有很多人有過這樣的經驗吧。"},{ja:"私の家の近くにある本屋は、店長がとても工夫をしている。おすすめの本には手書きのカードをつけ、月に一度は作家を招いて小さな会を開く。週末には子どもに絵本を読む時間もあり、いつも親子連れでにぎやかだ。売り上げは決して多くないそうだが、地域の人が集まる場所になっている。",zh:"我家附近的書店，店長非常用心。推薦的書會附上手寫卡片，每個月還會邀請一次作家舉辦小型聚會。週末也有為孩子朗讀繪本的時間，總是有很多親子來訪，十分熱鬧。聽說營業額絕對稱不上多，但這裡已成為社區居民聚集的地方。"},{ja:"本屋を守るために、私たちにできることは何だろうか。難しく考える必要はない。たまには近くの本屋に足を運んで、一冊でもいいから本を買うことだ。それが、町の文化を守る小さな一歩になると私は信じている。",zh:"為了守護書店，我們能做些什麼呢？不需要想得太複雜，只要偶爾到附近的書店走走，哪怕只買一本書也好。我相信，這會成為守護城鎮文化的一小步。"}],vocab:[{word:"次々",reading:"つぎつぎ",meaning:"一個接一個"},{word:"仕方がない",reading:"しかたがない",meaning:"沒辦法、無可奈何"},{word:"出会う",reading:"であう",meaning:"遇見、邂逅"},{word:"結局",reading:"けっきょく",meaning:"結果、最後"},{word:"招く",reading:"まねく",meaning:"邀請"},{word:"決して",reading:"けっして",meaning:"絕對（不）"},{word:"地域",reading:"ちいき",meaning:"地區、社區"}],questions:[{question:"筆者が考える本屋の良さは何か。",questionZh:"作者認為書店的優點是什麼？",options:["探していなかった本に出会えること","ネットより本が安く買えること","次の日に家に届けてくれること","何百冊も持ち歩けること"]},{question:"筆者の家の近くにある本屋について、正しいものはどれか。",questionZh:"關於作者家附近的書店，哪一項正確？",options:["月に一度、作家を招いて会を開いている","売り上げがとても多い","子どもは入ることができない","電子書籍だけを売っている"]},{question:"筆者が読者にすすめていることは何か。",questionZh:"作者建議讀者做什麼？",options:["近くの本屋に行って本を買うこと","本屋でアルバイトをすること","電子書籍を読むのをやめること","自分で本屋を開くこと"]}]},{id:"n3-r06",title:"スマホ教室で学んだこと",titleZh:"在手機教室學到的事",topic:"社會",paragraphs:[{ja:"私は大学二年生です。半年前から、週に一度、公民館で開かれている「シニアのためのスマホ教室」でボランティアをしています。参加者は六十代から八十代の方々で、毎回十人ほどが集まります。",zh:"我是大學二年級學生。從半年前開始，每週一次在公民館舉辦的「銀髮族手機教室」當志工。參加者是六十多歲到八十多歲的長輩，每次大約有十個人來。"},{ja:"始めたばかりのころ、私はとても戸惑いました。「アプリ」や「ダウンロード」という言葉を使っても、なかなか伝わらないのです。ある日、八十歳の女性に「あなたの説明は速すぎて、メモが間に合わないわ」と言われてしまいました。私にとって当たり前のことが、ほかの人にとってはそうではないのだと気づきました。",zh:"剛開始的時候，我非常不知所措。就算使用「App」或「下載」這些詞，對方也很難理解。有一天，一位八十歲的女士對我說：「你講得太快了，我來不及抄筆記。」我這才發現，對我來說理所當然的事，對別人來說並非如此。"},{ja:"それからは、難しい言葉をできるだけ使わず、一つずつゆっくり説明するように心がけています。また、大事な手順は紙に大きく書いて渡すことにしました。何度同じ質問をされても、嫌な顔をしないようにしています。",zh:"從那之後，我留意盡量不用困難的詞彙，一步一步慢慢說明。另外，我也決定把重要的步驟用大字寫在紙上交給他們。不管同樣的問題被問幾次，我都盡量不露出不耐煩的表情。"},{ja:"先月、あの女性が「孫とビデオ通話ができたのよ」と、うれしそうに報告してくれました。遠くに住むお孫さんの顔を見ながら話せて、涙が出たそうです。その話を聞いて、私も胸が熱くなりました。教えているつもりでしたが、実は私のほうが多くのことを学んでいるのかもしれません。",zh:"上個月，那位女士開心地告訴我：「我能和孫子視訊通話了喔！」聽說她一邊看著住在遠方的孫子的臉一邊說話，忍不住流下了眼淚。聽了這件事，我也感到心頭一熱。我原以為自己是在教人，但說不定其實是我學到了更多。"}],vocab:[{word:"参加者",reading:"さんかしゃ",meaning:"參加者"},{word:"戸惑う",reading:"とまどう",meaning:"不知所措、困惑"},{word:"当たり前",reading:"あたりまえ",meaning:"理所當然"},{word:"気づく",reading:"きづく",meaning:"察覺、發現"},{word:"心がける",reading:"こころがける",meaning:"留意、注意做到"},{word:"手順",reading:"てじゅん",meaning:"步驟、程序"},{word:"報告",reading:"ほうこく",meaning:"報告"}],questions:[{question:"女性に言われた言葉から、筆者は何に気づいたか。",questionZh:"從那位女士說的話中，作者發現了什麼？",options:["自分には当たり前のことが、ほかの人にはそうではないこと","高齢者にはスマホは必要ないこと","メモを取るのは時間のむだだということ","ボランティアをやめるべきだということ"]},{question:"筆者が今、心がけていることはどれか。",questionZh:"作者現在留意做到的是哪一項？",options:["難しい言葉を使わず、ゆっくり説明すること","できるだけ速く説明すること","同じ質問には答えないこと","大事な手順は口だけで説明すること"]}]},{id:"n3-r07",title:"ツバメが帰ってくる家",titleZh:"燕子歸來的家",topic:"自然",paragraphs:[{ja:"毎年春になると、私の家の玄関の上にツバメがやってくる。ツバメは冬の間、東南アジアなどの暖かい地域で過ごし、春になると日本に戻ってくる渡り鳥だ。驚くことに、前の年と同じ巣に帰ってくることも多いという。",zh:"每年一到春天，就會有燕子飛到我家玄關上方。燕子是一種候鳥，冬天在東南亞等溫暖地區度過，春天再回到日本。令人驚訝的是，據說牠們常常會回到前一年的同一個巢。"},{ja:"ツバメは、泥やかれた草を口で運んで、少しずつ巣を作る。わざわざ人の家の近くに巣を作るのは、カラスやヘビなどの敵が人間を怖がって、あまり近づかないからだそうだ。つまり、ツバメは人間を利用して、自分の子どもを守っているのである。",zh:"燕子會用嘴叼來泥土和枯草，一點一點地築巢。聽說牠們特地把巢築在人家附近，是因為烏鴉、蛇等天敵害怕人類，不太會靠近。也就是說，燕子是利用人類來保護自己的孩子。"},{ja:"巣ができると、やがて卵を産み、二週間ほどでひながかえる。親鳥は一日に何百回も虫を運んでくる。ひなが大きな口を開けて、えさを待っている姿は、何度見てもかわいい。ただ、玄関の前にふんが落ちるので、毎朝そうじをするのは少し大変だ。",zh:"巢築好後，不久就會產卵，大約兩週雛鳥就會孵出來。親鳥一天要叼蟲回來好幾百次。雛鳥張大嘴巴等待餵食的模樣，不管看幾次都很可愛。只是糞便會掉在玄關前，每天早上打掃有點辛苦。"},{ja:"最近は、ふんを嫌がって巣を壊してしまう家や、巣を作れない新しい建物が増えているため、ツバメの数が減っているそうだ。昔から日本では、ツバメが巣を作る家は縁起がいいと言われてきた。少しの手間はかかるが、私はこれからもツバメを迎えたいと思っている。",zh:"聽說最近因為嫌糞便髒而把巢弄壞的人家，以及無法築巢的新建築越來越多，燕子的數量正在減少。在日本，自古以來就說燕子築巢的人家會帶來好運。雖然要多花點工夫，但我今後仍想迎接燕子的到來。"}],vocab:[{word:"渡り鳥",reading:"わたりどり",meaning:"候鳥"},{word:"巣",reading:"す",meaning:"巢"},{word:"敵",reading:"てき",meaning:"敵人、天敵"},{word:"利用",reading:"りよう",meaning:"利用"},{word:"姿",reading:"すがた",meaning:"姿態、模樣"},{word:"縁起",reading:"えんぎ",meaning:"吉凶兆頭"},{word:"手間",reading:"てま",meaning:"工夫、勞力"}],questions:[{question:"ツバメが人の家の近くに巣を作るのはなぜか。",questionZh:"燕子為什麼在人家附近築巢？",options:["敵が人間を怖がって、あまり近づかないから","人間がえさをくれるから","家の近くは冬でも暖かいから","家の近くには泥がたくさんあるから"]},{question:"ツバメの数が減っている理由として、正しいものはどれか。",questionZh:"關於燕子數量減少的原因，哪一項正確？",options:["巣を壊されたり、巣を作れる建物が減ったりしているから","東南アジアが寒くなったから","虫が増えすぎたから","縁起が悪い鳥だと言われているから"]}]},{id:"n3-r08",title:"山の天気は変わりやすい",titleZh:"山上的天氣變化多端",topic:"自然",paragraphs:[{ja:"「山の天気は変わりやすい」という言葉を聞いたことがありますか。朝は晴れていたのに、昼ごろ急に雲が出て、雨が降り出すことは、山ではよくあります。これにはちゃんとした理由があります。",zh:"大家聽過「山上的天氣變化多端」這句話嗎？早上明明是晴天，到了中午卻突然出現雲層、開始下雨，這在山上是常有的事。這背後是有明確原因的。"},{ja:"晴れた日、太陽の光で地面が温められると、山にそって空気が上へ上がっていきます。空気は高い所へ行くほど冷えるので、その中の水蒸気が小さな水のつぶになり、雲ができます。そのため、山では午後になると雲が増えやすく、場合によっては激しい雨や雷になるのです。",zh:"晴天時，地面被陽光加熱後，空氣會沿著山往上升。空氣越往高處越冷，其中的水蒸氣會變成小水滴，形成雲。因此，山上到了下午雲容易變多，有時還會變成大雨或雷雨。"},{ja:"また、山の上は平地よりも気温がずっと低くなります。一般に、百メートル高くなるごとに、気温は約〇・六度下がると言われています。ふもとが二十五度でも、標高二千メートルの山頂では、十三度くらいになる計算です。さらに風が強いと、体はもっと寒く感じます。",zh:"此外，山上的氣溫比平地低得多。一般來說，每升高一百公尺，氣溫約下降零點六度。就算山腳是二十五度，計算起來，海拔兩千公尺的山頂大約只有十三度。再加上風大的話，身體會覺得更冷。"},{ja:"ですから、山に登るときは、天気がよくても雨具と上着を必ず持っていきましょう。そして、できるだけ朝早く出発して、午後の早い時間に下りるように計画することが大切です。「少しでもおかしい」と感じたら、無理をしないで引き返す勇気も持ってください。",zh:"所以，登山時就算天氣很好，也一定要帶雨具和外套。而且，盡量一早出發、計畫在下午早一點的時間下山是很重要的。只要覺得「有一點不對勁」，也請拿出不勉強、折返下山的勇氣。"}],vocab:[{word:"地面",reading:"じめん",meaning:"地面"},{word:"冷える",reading:"ひえる",meaning:"變冷、冷卻"},{word:"激しい",reading:"はげしい",meaning:"激烈的、猛烈的"},{word:"一般",reading:"いっぱん",meaning:"一般"},{word:"計算",reading:"けいさん",meaning:"計算"},{word:"出発",reading:"しゅっぱつ",meaning:"出發"},{word:"勇気",reading:"ゆうき",meaning:"勇氣"}],questions:[{question:"山で午後に雲が増えやすいのはなぜか。",questionZh:"山上為什麼到了下午雲容易變多？",options:["温められた空気が上がって冷え、雲ができるから","午後は太陽の光が弱くなるから","山の上は風が吹かないから","午後になると山の上の気温が上がるから"]},{question:"ふもとが二十五度のとき、標高二千メートルの山頂は何度くらいか。",questionZh:"山腳是二十五度時，海拔兩千公尺的山頂大約幾度？",options:["十三度くらい","二十五度くらい","五度くらい","二十度くらい"]},{question:"筆者のアドバイスと合わないものはどれか。",questionZh:"哪一項不符合作者的建議？",options:["天気がよければ雨具は持たなくてよい","できるだけ朝早く出発する","午後の早い時間に下りるように計画する","おかしいと感じたら引き返す"]}]},{id:"n3-r09",title:"夕焼けはなぜ赤いのか",titleZh:"晚霞為什麼是紅色的",topic:"科學",paragraphs:[{ja:"晴れた日の昼、空は青い。ところが夕方になると、西の空はオレンジ色や赤に変わる。同じ太陽の光なのに、どうして時間によって空の色が違うのだろうか。",zh:"晴天的中午，天空是藍色的。然而到了傍晚，西邊的天空卻變成橘色或紅色。明明是同樣的陽光，為什麼天空的顏色會隨時間不同呢？"},{ja:"太陽の光は白く見えるが、実はいろいろな色の光が混ざってできている。虹が七色に見えるのはそのためだ。光が空気の中を通るとき、空気のとても小さなつぶにぶつかって、いろいろな方向に散らばる。このとき、青い光は赤い光よりも散らばりやすいという性質がある。",zh:"陽光看起來是白色的，其實是由各種顏色的光混合而成。彩虹看起來有七種顏色就是這個緣故。光通過空氣時，會撞上空氣中非常微小的粒子，往各個方向散開。這時，藍光有比紅光更容易散開的性質。"},{ja:"昼間は太陽が高い位置にあるので、光が空気の中を通る距離は短い。散らばった青い光が空全体に広がるため、私たちの目には空が青く見える。一方、夕方は太陽が低い位置にあるので、光は空気の中を長い距離通ってくる。その間に青い光はほとんど散らばってしまい、散らばりにくい赤やオレンジの光だけが私たちの目に届く。これが夕焼けの正体だ。",zh:"白天太陽在高處，光通過空氣的距離較短。散開的藍光擴散到整片天空，所以在我們眼中天空是藍色的。另一方面，傍晚太陽在低處，光要穿過很長距離的空氣才會到達。這段期間藍光幾乎都散開了，只有不易散開的紅光和橘光傳到我們眼中。這就是晚霞的真面目。"},{ja:"ちなみに、火星の夕焼けは青く見えるそうだ。火星の空気には細かい砂がたくさん含まれていて、地球とは光の散らばり方が違うからである。いつも見ている空も、理由を知ると少し違って見えてくるのではないだろうか。",zh:"順帶一提，據說火星的晚霞看起來是藍色的。因為火星的大氣中含有大量細沙，光的散射方式和地球不同。平常看慣的天空，知道原因之後，是不是看起來也有點不一樣了呢？"}],vocab:[{word:"混ざる",reading:"まざる",meaning:"混合、摻雜"},{word:"性質",reading:"せいしつ",meaning:"性質"},{word:"位置",reading:"いち",meaning:"位置"},{word:"距離",reading:"きょり",meaning:"距離"},{word:"全体",reading:"ぜんたい",meaning:"整體、全部"},{word:"一方",reading:"いっぽう",meaning:"另一方面"},{word:"含む",reading:"ふくむ",meaning:"包含、含有"}],questions:[{question:"青い光にはどのような性質があるか。",questionZh:"藍光有什麼樣的性質？",options:["赤い光よりも散らばりやすい","赤い光よりも遠くまで届く","空気のつぶにぶつからない","夕方だけ強くなる"]},{question:"夕方、空が赤く見えるのはなぜか。",questionZh:"傍晚天空為什麼看起來是紅色的？",options:["光が長い距離を通る間に、青い光が散らばってしまうから","夕方は太陽そのものが赤くなるから","夕方になると空気のつぶがなくなるから","西の空には虹が出るから"]},{question:"火星の夕焼けについて、文章の内容と合うものはどれか。",questionZh:"關於火星的晚霞，哪一項符合文章內容？",options:["青く見える","地球と同じように赤く見える","砂のせいで何も見えない","七色に見える"]}]},{id:"n3-r10",title:"消えたプリン",titleZh:"消失的布丁",topic:"推理",paragraphs:[{ja:"日曜日の午後三時、母は「夜みんなで食べようね」と言って、駅前の有名な店のプリンを四つ冷蔵庫に入れ、買い物に出かけた。ところが五時に私が冷蔵庫を開けると、プリンが一つ足りない。台所のごみ箱には、空になった容器とスプーンが捨ててあった。",zh:"星期天下午三點，媽媽說「晚上大家一起吃吧」，把四個車站前名店的布丁放進冰箱後就出門買東西了。可是五點我打開冰箱時，布丁少了一個。廚房的垃圾桶裡丟著吃空的容器和湯匙。"},{ja:"家にいたのは、私と弟のケンタ、そして祖父の三人だ。甘いものが大好きな祖父が、まず怪しいと思った。しかし祖父は「昼ご飯のあとから、ずっと部屋で寝ていた」と言う。そういえば、四時ごろ私が祖父の部屋の前を通ったとき、大きないびきが聞こえていた。",zh:"在家的只有我、弟弟健太和爺爺三個人。我首先懷疑最愛吃甜食的爺爺。但爺爺說：「吃完午飯後就一直在房間睡覺。」這麼說來，四點左右我經過爺爺房門前時，確實聽到很大的鼾聲。"},{ja:"次にケンタに聞くと、「僕は三時からさっきまで、ずっと公園でサッカーをしていたよ。プリンなんて知らない」と答えた。たしかに、私が二階から下りてくる少し前に、玄関のほうから「ただいま」という声が聞こえた。",zh:"接著我問健太，他回答：「我從三點到剛才一直在公園踢足球啊，什麼布丁我不知道。」的確，在我從二樓下來前不久，有聽到玄關那邊傳來「我回來了」的聲音。"},{ja:"私は玄関に行って、ケンタの靴を見た。白いスニーカーはきれいで、少しもぬれていない。傘立ての傘も乾いたままだ。私は窓の外を見た。今日は四時から四時半まで強い雨が降った。公園の土は、まだどろどろのはずだ。",zh:"我走到玄關看了看健太的鞋子。白色運動鞋乾乾淨淨，一點也沒濕。傘架上的傘也還是乾的。我望向窗外。今天從四點到四點半下了一場大雨，公園的地面應該還是一片泥濘才對。"},{ja:"「なるほど、プリンを食べたのはあの人だ」。私はにっこり笑って、その人の部屋のドアをノックした。",zh:"「原來如此，吃掉布丁的就是那個人。」我微微一笑，敲了敲那個人的房門。"}],vocab:[{word:"冷蔵庫",reading:"れいぞうこ",meaning:"冰箱"},{word:"容器",reading:"ようき",meaning:"容器"},{word:"怪しい",reading:"あやしい",meaning:"可疑的"},{word:"玄関",reading:"げんかん",meaning:"玄關、門口"},{word:"乾く",reading:"かわく",meaning:"乾"},{word:"傘立て",reading:"かさたて",meaning:"傘架"}],questions:[{question:"「私」がプリンが足りないことに気づいたのは何時か。",questionZh:"「我」是在幾點發現布丁少了一個？",options:["五時","三時","四時","四時半"]},{question:"祖父が犯人ではないと考えられる理由は何か。",questionZh:"可以認為爺爺不是犯人的理由是什麼？",options:["四時ごろ、部屋からいびきが聞こえていたから","甘いものが嫌いだから","母と一緒に買い物に出かけていたから","公園でサッカーをしていたから"]},{question:"プリンを食べたのはだれか。また、その手がかりは何か。",questionZh:"吃掉布丁的是誰？線索又是什麼？",options:["ケンタ。雨が降ったのに、靴も傘もぬれていなかったから","祖父。甘いものが大好きだから","母。プリンを買ってきた本人だから","ケンタ。ごみ箱に子ども用のスプーンがあったから"]}]},{id:"n3-r11",title:"割れた花瓶",titleZh:"破掉的花瓶",topic:"推理",paragraphs:[{ja:"放課後、美術部の部室に入ると、森先生が困った顔をしていた。先生の机の上にあったガラスの花瓶が、昼休みの間に割れていたのだ。旅行先で買ってきた大切な花瓶だったという。割れたガラスは、先生がもう片づけてしまったので、机の上には何も残っていなかった。",zh:"放學後，我一走進美術社社團教室，就看到森老師一臉困擾。原來放在老師桌上的玻璃花瓶，在午休時間被打破了。聽說那是老師旅行時買回來的珍貴花瓶。破掉的玻璃老師已經收拾好了，所以桌上什麼也沒留下。"},{ja:"昼休みに部室に来たのは、佐藤君、鈴木さん、高橋君の三人だ。部長の私に、先生は小さな声で言った。「三人には、何が壊れたのかは言わないでおこう。犯人なら、知っているはずだからね」。そして先生は三人を呼び、「昼休みに、私の机の上の物が一つ壊されていました。何か知りませんか」とだけ聞いた。",zh:"午休時來過社團教室的，是佐藤、鈴木和高橋三個人。老師小聲地對身為社長的我說：「先別告訴他們三個是什麼東西壞了。如果是犯人，應該會知道的。」接著老師把三人叫來，只問了一句：「午休時，我桌上有一樣東西被弄壞了。你們知道些什麼嗎？」"},{ja:"佐藤君は「僕は十二時半ごろ、絵の道具を取りに来ただけです。机のほうには行っていません」と答えた。鈴木さんは「私は一時前に、借りていたノートを返しに来ました。でも、机の上はちゃんと見ていませんでした」と言った。",zh:"佐藤回答：「我十二點半左右只是來拿畫具而已，沒有走到桌子那邊。」鈴木說：「我在一點前來還借的筆記本，但我沒有仔細看桌上。」"},{ja:"最後に高橋君が言った。「僕はここでお弁当を食べていました。でも、ガラスが割れるような音は聞いていませんよ。先生の机にも近づいていないし」。",zh:"最後高橋說：「我在這裡吃便當，可是我沒聽到像玻璃破掉的聲音喔，而且我也沒靠近老師的桌子。」"},{ja:"三人の話を聞いて、私はすぐに気づいた。この中の一人が、知らないはずのことを話している。先生も同じことに気づいたようで、私と目を合わせて、静かにうなずいた。",zh:"聽完三人的話，我立刻察覺到了：他們之中有一個人，說出了本來不該知道的事。老師似乎也注意到了同一件事，與我對望一眼，靜靜地點了點頭。"}],vocab:[{word:"片づける",reading:"かたづける",meaning:"收拾、整理"},{word:"残る",reading:"のこる",meaning:"留下、剩下"},{word:"犯人",reading:"はんにん",meaning:"犯人"},{word:"道具",reading:"どうぐ",meaning:"工具、用具"},{word:"返す",reading:"かえす",meaning:"歸還"},{word:"近づく",reading:"ちかづく",meaning:"靠近、接近"}],questions:[{question:"先生が三人に、何が壊れたのかを言わなかったのはなぜか。",questionZh:"老師為什麼沒告訴三人是什麼東西壞了？",options:["犯人なら壊れた物を知っているはずだから","花瓶のことを忘れていたから","三人を怒らせたくなかったから","壊れた物がまだ見つかっていなかったから"]},{question:"鈴木さんは何のために部室に来たか。",questionZh:"鈴木是為了什麼來社團教室的？",options:["借りていたノートを返すため","お弁当を食べるため","絵の道具を取るため","先生に質問するため"]},{question:"花瓶を割ったのはだれか。また、そう考えられる理由は何か。",questionZh:"打破花瓶的是誰？這麼認為的理由是什麼？",options:["高橋君。壊れた物がガラスだと知っていたから","佐藤君。十二時半に部室に来たから","鈴木さん。机の上をちゃんと見ていなかったから","高橋君。部室でお弁当を食べていたから"]}]},{id:"n3-r12",title:"雨の夜の喫茶店",titleZh:"雨夜的咖啡店",topic:"推理",paragraphs:[{ja:"叔父は昔、警察で働いていた。今は退職して、町で小さな喫茶店をしている。ある雨の夜、近所の和菓子屋の主人、松本さんが店に飛び込んできた。「レジのお金がなくなったんです。どうしたらいいでしょう」",zh:"叔叔以前在警察局工作，現在退休了，在鎮上經營一家小咖啡店。某個下雨的夜晚，附近和菓子店的老闆松本先生衝進店裡：「收銀機裡的錢不見了！我該怎麼辦才好？」"},{ja:"松本さんの話によると、店を閉めたのは午後六時。レジのお金を数えて袋に入れたあと、奥の部屋で十分ほど電話をしていた。戻ってくると、お金が入った袋が消えていたという。その日に働いていたのは、アルバイトの山口さんと、店員の川田さんの二人だ。",zh:"根據松本先生的說法，店是在下午六點關門的。他把收銀機的錢數好裝進袋子後，在裡面的房間講了十分鐘左右的電話。回來時，裝著錢的袋子就不見了。那天上班的，是工讀生山口小姐和店員川田小姐兩個人。"},{ja:"山口さんは「六時に店を出て、六時五分のバスで家に帰りました」と話したそうだ。川田さんは「五時半に仕事が終わって、すぐに歩いて帰りました。家に着いたのは六時ごろです。途中で雨が降り出して、びしょぬれになりましたよ」と言ったらしい。",zh:"據說山口小姐說：「我六點離開店裡，搭六點五分的公車回家。」川田小姐則說：「我五點半下班，馬上就走路回家了，到家大概六點。半路上開始下雨，我淋成了落湯雞呢。」"},{ja:"叔父はコーヒーを一口飲んで、窓の外を見た。「松本さん、今日、雨が降り始めたのは何時ごろでしたか」「たしか六時半ごろです。電話をしているとき、窓に雨の当たる音がしましたから」。叔父は静かにうなずいた。「どうやら、うそをついている人がいるようですね」",zh:"叔叔喝了一口咖啡，望向窗外。「松本先生，今天大概是幾點開始下雨的？」「應該是六點半左右。我在講電話時聽到雨打在窗戶上的聲音。」叔叔靜靜地點了點頭：「看來，有人在說謊呢。」"}],vocab:[{word:"退職",reading:"たいしょく",meaning:"退休、離職"},{word:"近所",reading:"きんじょ",meaning:"附近、鄰近"},{word:"主人",reading:"しゅじん",meaning:"老闆、主人"},{word:"飛び込む",reading:"とびこむ",meaning:"衝進、跳進"},{word:"数える",reading:"かぞえる",meaning:"數、計算"},{word:"戻る",reading:"もどる",meaning:"返回、回來"},{word:"途中",reading:"とちゅう",meaning:"途中、半路"}],questions:[{question:"松本さんがお金がないことに気づいたのはいつか。",questionZh:"松本先生是什麼時候發現錢不見的？",options:["奥の部屋で電話をして、戻ってきたとき","朝、店を開けたとき","山口さんが帰る前","叔父の喫茶店に来たとき"]},{question:"この日、雨が降り始めたのは何時ごろか。",questionZh:"這一天大約幾點開始下雨？",options:["六時半ごろ","五時半ごろ","六時ごろ","六時五分ごろ"]},{question:"うそをついているのはだれか。また、その理由は何か。",questionZh:"說謊的是誰？理由是什麼？",options:["川田さん。六時ごろ家に着いたのに、帰る途中で雨にぬれたと言ったから","山口さん。六時五分にはバスが走っていないから","松本さん。電話をしていたと言ったから","川田さん。五時半に仕事が終わったと言ったから"]}]},{id:"n3-r13",title:"お弁当を続けるコツ",titleZh:"持續帶便當的訣竅",topic:"生活",paragraphs:[{ja:"社会人になって二年目の春、私はお弁当を作り始めた。毎日の昼ご飯代が思ったよりかかっていることに気づき、少しでも節約しようと考えたのだ。ところが、張り切っていろいろなおかずを作ったせいで、朝の準備に一時間もかかってしまった。結局、三日で疲れてやめてしまった。",zh:"出社會第二年的春天，我開始自己做便當。因為發現每天的午餐費比想像中還多，想說多少節省一點。沒想到，因為幹勁十足地做了各式各樣的配菜，早上光是準備就花了整整一個小時。結果三天就累得放棄了。"},{ja:"そんなとき、料理が得意な先輩が、続けるためのコツを教えてくれた。一つ目は、夕食を少し多めに作って、その残りを次の日のお弁当に入れることだ。こうすれば、朝は詰めるだけで済む。二つ目は、週末に野菜をゆでたり肉に味をつけたりして、冷凍しておくことである。",zh:"就在那時，擅長做菜的前輩教了我持續下去的訣竅。第一，晚餐稍微多做一點，把剩下的放進隔天的便當。這樣一來，早上只要裝進便當盒就好。第二，週末先把蔬菜燙好、把肉調味，然後冷凍起來。"},{ja:"先輩はさらに、「毎日完璧なお弁当を作ろうとしないこと」とも言った。おかずが一品だけの日があってもいいし、疲れた日はおにぎりだけでもいい。どうしても無理な朝は、外で買えばいいのだ。そう考えると、気持ちがずっと楽になった。",zh:"前輩還說：「不要想著每天都做出完美的便當。」有幾天只有一道配菜也沒關係，累的日子只帶飯糰也可以。真的做不到的早上，去外面買就好了。這樣一想，心情就輕鬆多了。"},{ja:"先輩のやり方をまねしてから、もう半年になる。今では朝の準備は十五分ほどで終わり、一か月の食費もかなり減った。何より、自分で作ったお弁当を食べると、午後の仕事も頑張ろうという気持ちになる。無理をしないことが、長く続ける一番の秘訣なのだと思う。",zh:"模仿前輩的做法到現在已經半年了。如今早上的準備大約十五分鐘就能完成，一個月的伙食費也少了不少。最重要的是，吃著自己做的便當，就會覺得下午的工作也要好好加油。我認為，不勉強自己，正是長久持續下去的最大祕訣。"}],vocab:[{word:"節約",reading:"せつやく",meaning:"節省、節約"},{word:"張り切る",reading:"はりきる",meaning:"幹勁十足、起勁"},{word:"詰める",reading:"つめる",meaning:"裝滿、塞進"},{word:"冷凍",reading:"れいとう",meaning:"冷凍"},{word:"完璧",reading:"かんぺき",meaning:"完美"},{word:"食費",reading:"しょくひ",meaning:"伙食費、餐費"},{word:"秘訣",reading:"ひけつ",meaning:"祕訣"}],questions:[{question:"筆者が三日でお弁当作りをやめてしまったのはなぜか。",questionZh:"作者為什麼三天就放棄做便當了？",options:["張り切っていろいろなおかずを作り、朝の準備に時間がかかったから","毎日の昼ご飯代が思ったより安いとわかったから","料理が苦手で、おいしいおかずが作れなかったから","先輩に、毎日作らなくてもいいと言われたから"]},{question:"先輩が教えたコツとして、正しいものはどれか。",questionZh:"關於前輩教的訣竅，哪一項正確？",options:["夕食を多めに作り、残りを次の日のお弁当に入れる","毎朝一時間かけて、新しいおかずを何品も作る","週末に作ったおかずは、その日のうちに全部食べる","野菜や肉は冷凍しないで、毎朝買いに行く"]},{question:"筆者の考えに合うものはどれか。",questionZh:"下列哪一項符合作者的想法？",options:["無理をしないことが、長く続ける秘訣だ","お弁当は毎日完璧に作らなければならない","節約するなら、外で買うほうがよい","朝の準備には、時間をかけたほうがよい"]}]},{id:"n3-r14",title:"招き猫の手",titleZh:"招財貓的手",topic:"文化",paragraphs:[{ja:"日本の店に入ると、レジの横などで、片手を上げた猫の置物を見かけることがある。これは「招き猫」と呼ばれ、商売がうまくいくようにという願いを込めて飾られる物だ。外国人の観光客にも人気があり、お土産に買っていく人も多い。",zh:"走進日本的店家，有時會在收銀台旁邊等地方看到舉著一隻手的貓擺飾。這叫做「招き猫」（招財貓），是人們寄託了生意興隆的心願而擺放的東西。它在外國觀光客之間也很受歡迎，很多人會買回去當伴手禮。"},{ja:"招き猫の始まりについては、いくつかの話が伝わっている。その一つが、東京のあるお寺の話だ。昔、ある殿様がお寺の前を通りかかると、門の前にいた猫が、まるで「こちらへ」と呼ぶように前足を動かした。殿様がお寺に入って休んでいると、急に激しい雨が降り出した。雨にぬれずに済んだ殿様は猫に感謝し、そのお寺を大切にしたという。",zh:"關於招財貓的由來，流傳著好幾種說法，其中之一是東京某座寺廟的故事。從前，有位領主經過寺廟前時，門口的貓彷彿在說「這邊請」似地揮動前腳。領主進寺裡休息時，突然下起了大雨。沒被雨淋濕的領主很感謝那隻貓，從此便很照顧那座寺廟。"},{ja:"招き猫は、上げている手によって意味が違うと言われている。右手を上げた猫はお金を、左手を上げた猫はお客さんを招くそうだ。両手を上げた猫もいるが、「欲張りだ」と言って好まない人もいる。また、手が高く上がっているほど、遠くから幸せを招くとも言われている。",zh:"據說招財貓舉的手不同，意義也不一樣。舉右手的貓招財，舉左手的貓則招來客人。也有舉起雙手的貓，但有些人認為「太貪心了」而不喜歡。另外，也有一說是手舉得越高，就越能從遠方招來幸福。"},{ja:"最近は、ピンクや金色など、さまざまな色の招き猫も売られている。形や色は時代とともに変わっても、幸せを願う人々の気持ちは昔から変わらないのだろう。今度招き猫を見かけたら、どちらの手を上げているか確かめてみてはどうだろうか。",zh:"最近也有粉紅色、金色等各種顏色的招財貓在販售。就算形狀和顏色隨著時代改變，人們祈求幸福的心情想必自古至今都沒有改變吧。下次看到招財貓時，不妨確認一下牠舉的是哪一隻手吧？"}],vocab:[{word:"置物",reading:"おきもの",meaning:"擺飾、裝飾品"},{word:"見かける",reading:"みかける",meaning:"看到、偶然看見"},{word:"商売",reading:"しょうばい",meaning:"生意、買賣"},{word:"込める",reading:"こめる",meaning:"寄託、灌注（心意）"},{word:"殿様",reading:"とのさま",meaning:"（日本古時的）領主、大人"},{word:"欲張り",reading:"よくばり",meaning:"貪心（的人）"},{word:"確かめる",reading:"たしかめる",meaning:"確認、查明"}],questions:[{question:"お寺の話の内容と合うものはどれか。",questionZh:"下列哪一項符合寺廟故事的內容？",options:["猫に呼ばれて寺に入った殿様は、雨にぬれずに済んだ","殿様は激しい雨の中で、ぬれていた猫を助けた","猫が殿様のところへ、たくさんのお金を運んできた","雨が降り出したので、猫がお寺の中へ逃げ込んだ"]},{question:"左手を上げた招き猫は、何を招くと言われているか。",questionZh:"據說舉左手的招財貓會招來什麼？",options:["お客さん","お金","よい天気","長生き"]},{question:"両手を上げた招き猫について、文章ではどう述べられているか。",questionZh:"關於舉起雙手的招財貓，文章中是怎麼說的？",options:["欲張りだと考えて、好まない人もいる","いちばん人気があって、よく売れている","遠くから幸せを招くと言われている","昔はお寺にしか置かれていなかった"]}]},{id:"n3-r15",title:"フードバンクを知っていますか",titleZh:"你知道食物銀行嗎",topic:"社會",paragraphs:[{ja:"皆さんは「フードバンク」という活動を知っていますか。フードバンクとは、まだ食べられるのに売ることができなくなった食品を集めて、食べ物に困っている人や施設に無料で届ける活動のことです。日本では二〇〇〇年ごろに始まり、今では全国に広がっています。",zh:"大家知道「食物銀行」這項活動嗎？所謂食物銀行，是指收集還能吃卻已經無法販售的食品，免費送給缺乏食物的人或相關機構的活動。日本大約從二〇〇〇年左右開始，現在已經推廣到全國各地。"},{ja:"店や工場では、毎日たくさんの食品が捨てられています。たとえば、箱に少し傷がついたものや、ラベルの印刷を間違えたもの、賞味期限が近づいたものなどです。中身には何の問題もないのに、商品としては売れないのです。こうした「食品ロス」を減らすことも、フードバンクの大切な役割です。",zh:"商店和工廠每天都會丟掉大量的食品，例如盒子有一點刮傷的、標籤印錯的、或是快到賞味期限的東西。裡面的東西明明一點問題也沒有，卻無法當作商品販售。減少這類「食物浪費」，也是食物銀行的重要任務。"},{ja:"私は先月、近所のフードバンクでボランティアをしました。仕事は、届いた食品を種類ごとに分けて、賞味期限を一つずつ確認することでした。缶詰やお米、お菓子など、思ったよりいろいろな物があり、中には家庭から寄付された物もありました。",zh:"我上個月在附近的食物銀行當志工。工作內容是把送來的食品依種類分好，再一個一個確認賞味期限。罐頭、米、零食等等，種類比想像中還多，其中也有一般家庭捐贈的東西。"},{ja:"家庭で余っている食品を集める「フードドライブ」という取り組みもあり、スーパーや市役所などに回収の箱が置かれています。ただし、賞味期限まで一か月以上あり、常温で保存できる物に限られることが多いので、注意が必要です。食べ物をむだにしないために、私たちにもできることがありそうです。",zh:"另外也有一種叫做「食物募集」的活動，收集家庭中多餘的食品，超市或市公所等地方都設有回收箱。不過，通常只限於距離賞味期限還有一個月以上、而且可以常溫保存的東西，這一點需要注意。為了不浪費食物，我們似乎也有能做的事。"}],vocab:[{word:"施設",reading:"しせつ",meaning:"機構、設施"},{word:"傷",reading:"きず",meaning:"傷痕、刮傷"},{word:"賞味期限",reading:"しょうみきげん",meaning:"賞味期限、最佳食用期限"},{word:"役割",reading:"やくわり",meaning:"任務、角色"},{word:"確認",reading:"かくにん",meaning:"確認"},{word:"寄付",reading:"きふ",meaning:"捐贈、捐款"},{word:"余る",reading:"あまる",meaning:"剩餘、多出來"}],questions:[{question:"フードバンクが集めているのは、どのような食品か。",questionZh:"食物銀行收集的是什麼樣的食品？",options:["まだ食べられるが、売れなくなった食品","賞味期限が過ぎてしまった古い食品","工場で新しく作られた高い食品","家庭で作った料理の食べ残し"]},{question:"筆者がボランティアでした仕事はどれか。",questionZh:"作者當志工時做的工作是哪一項？",options:["食品を種類ごとに分け、賞味期限を確認すること","困っている家庭に、食品を直接届けること","スーパーの前で、食品の寄付を呼びかけること","間違えたラベルを、工場で印刷し直すこと"]},{question:"フードドライブに食品を出すとき、注意することは何か。",questionZh:"把食品拿去參加食物募集時，要注意什麼？",options:["常温で保存できる物に限られることが多い","冷蔵庫で保存する物でも、何でも出せる","賞味期限が近い物ほど、喜ばれる","市役所に直接持っていかなければならない"]}]},{id:"n3-r16",title:"足もとの黄色い道",titleZh:"腳下的黃色道路",topic:"社會",paragraphs:[{ja:"駅のホームや歩道で、表面がでこぼこした黄色いブロックを見たことがあるだろう。これは「点字ブロック」と呼ばれ、目の不自由な人に、足の裏や白い杖で道を知らせるためのものだ。実はこのブロックは、一九六七年に岡山県で初めて置かれ、その後、世界中に広がったのである。",zh:"大家應該都在車站月台或人行道上，看過表面凹凸不平的黃色地磚吧。這叫做「點字磚」（導盲磚），是用來讓視障者透過腳底或白手杖得知道路的東西。其實這種地磚是一九六七年在岡山縣首次鋪設，之後才推廣到全世界的。"},{ja:"点字ブロックには、大きく分けて二つの種類がある。細長い線が並んだものは「この方向に進んでよい」、丸い点が並んだものは「ここで止まって注意する」という意味だ。点のブロックは、階段の前や横断歩道の手前、ホームの端などに置かれている。黄色が多いのは、少し見える人にとっても、周りと区別しやすい色だからだ。",zh:"點字磚大致可分為兩種。排列著細長線條的，意思是「可以往這個方向前進」；排列著圓點的，意思是「在這裡停下、注意」。圓點的地磚會鋪設在樓梯前、斑馬線前方，以及月台邊緣等地方。之所以多為黃色，是因為對還看得到一點的人來說，這是容易與周圍區分的顏色。"},{ja:"ところが、このブロックの上に自転車が止められていたり、大きな荷物が置かれていたりすることが少なくない。ブロックの上で立ち止まって、スマホを見ている人もいる。目の不自由な人にとっては、急に道がふさがれているのと同じで、ぶつかってけがをする危険もある。",zh:"然而，點字磚上停著腳踏車、放著大件行李的情況並不少見。也有人站在點字磚上停下來看手機。對視障者來說，這就等於道路突然被擋住，還有撞上而受傷的危險。"},{ja:"点字ブロックは、ただの模様ではなく、大切な「道」である。ブロックの上に物を置かない、立ち止まらない。それだけで、だれかの安全を守ることができる。明日から、自分の足もとを少し気にしてみてほしい。",zh:"點字磚不只是圖案，而是重要的「道路」。不在點字磚上放東西、不在上面停留，光是這樣就能守護某個人的安全。希望大家從明天起，稍微留意一下自己的腳下。"}],vocab:[{word:"表面",reading:"ひょうめん",meaning:"表面"},{word:"不自由",reading:"ふじゆう",meaning:"不方便、（身體）有障礙"},{word:"杖",reading:"つえ",meaning:"手杖、枴杖"},{word:"手前",reading:"てまえ",meaning:"前方、跟前"},{word:"端",reading:"はし",meaning:"邊緣、盡頭"},{word:"区別",reading:"くべつ",meaning:"區別、區分"},{word:"ふさぐ",reading:"ふさぐ",meaning:"堵塞、擋住"}],questions:[{question:"丸い点が並んだブロックは、何を知らせているか。",questionZh:"排列著圓點的地磚是在告訴人什麼？",options:["ここで止まって注意すること","この方向に進んでよいこと","近くに駅の入り口があること","ここに自転車を止めてよいこと"]},{question:"点字ブロックに黄色が多いのはなぜか。",questionZh:"點字磚為什麼大多是黃色的？",options:["少し見える人にも、周りと区別しやすいから","最初に作られた岡山県を表す色だから","夜になると、黄色は光って見えるから","自転車に乗る人が、よけやすいから"]},{question:"筆者が読者に求めていることは何か。",questionZh:"作者希望讀者做什麼？",options:["ブロックの上に物を置いたり、立ち止まったりしないこと","点字ブロックを増やすように、市に頼むこと","目の不自由な人を、駅まで案内すること","ブロックの模様を、もっときれいにすること"]}]},{id:"n3-r17",title:"ホタルの光",titleZh:"螢火蟲的光",topic:"自然",paragraphs:[{ja:"六月ごろ、きれいな川の近くでは、夜になるとホタルが光りながら飛ぶ姿が見られます。日本には五十種類ほどのホタルがいますが、よく知られているのはゲンジボタルです。ホタルの光は熱をほとんど出さないので、「冷たい光」とも呼ばれています。",zh:"六月左右，在乾淨的河川附近，一到晚上就能看到螢火蟲一邊發光一邊飛舞的身影。日本大約有五十種螢火蟲，其中最為人熟知的是源氏螢。螢火蟲的光幾乎不會發熱，所以也被稱為「冷光」。"},{ja:"ホタルが光るのは、主に仲間に合図を送るためです。オスは飛びながら光り、メスは草の葉の上で光って答えます。おもしろいことに、ゲンジボタルの光り方は地域によって違い、東日本では約四秒に一回、西日本では約二秒に一回光ると言われています。",zh:"螢火蟲發光，主要是為了向同伴傳送信號。公螢火蟲一邊飛一邊發光，母螢火蟲則在草葉上發光回應。有趣的是，源氏螢的發光方式因地區而異，據說在東日本大約四秒閃一次，在西日本則大約兩秒閃一次。"},{ja:"ホタルの一生の大部分は、実は水の中で過ごす時間です。幼虫は川の中で十か月ほど暮らし、カワニナという小さな貝を食べて育ちます。そして春になると陸に上がり、土の中でさなぎになります。成虫になってから生きられるのは、わずか一、二週間ほどです。",zh:"螢火蟲一生中的大部分時間，其實是在水中度過的。幼蟲在河裡生活大約十個月，以一種叫做川蜷的小型螺貝為食長大。到了春天就爬上陸地，在土裡化成蛹。變成成蟲之後，只能活短短一、兩個星期左右。"},{ja:"ホタルが育つには、きれいな水と、カワニナがすめる川、そして土の岸が必要です。しかし、川岸がコンクリートで固められたり、夜の町が明るくなりすぎたりして、ホタルが見られる場所は減ってきました。最近では、地域の人たちが川をそうじして、ホタルを呼び戻そうとする活動も行われています。",zh:"螢火蟲要成長，需要乾淨的水、能讓川蜷棲息的河川，以及泥土的河岸。但是，由於河岸被水泥封起來、夜晚的城鎮變得太亮等原因，能看到螢火蟲的地方越來越少了。最近也有當地居民清掃河川，希望把螢火蟲找回來的活動。"}],vocab:[{word:"仲間",reading:"なかま",meaning:"同伴、夥伴"},{word:"合図",reading:"あいず",meaning:"信號、暗號"},{word:"幼虫",reading:"ようちゅう",meaning:"幼蟲"},{word:"貝",reading:"かい",meaning:"貝類、螺貝"},{word:"成虫",reading:"せいちゅう",meaning:"成蟲"},{word:"わずか",reading:"わずか",meaning:"僅僅、只有一點點"},{word:"固める",reading:"かためる",meaning:"使堅固、加固"}],questions:[{question:"ホタルが光る主な理由は何か。",questionZh:"螢火蟲發光的主要原因是什麼？",options:["仲間に合図を送るため","冷えた体を温めるため","近づいてくる敵を驚かせるため","暗い川でえさの貝を探すため"]},{question:"ゲンジボタルについて、文章の内容と合うものはどれか。",questionZh:"關於源氏螢，哪一項符合文章內容？",options:["幼虫は川の中で、カワニナを食べて育つ","成虫になってから、一年ほど生きられる","どの地域でも、同じ速さで光っている","メスが飛びながら光り、オスが葉の上で答える"]},{question:"ホタルが見られる場所が減った理由として、文章で挙げられているものはどれか。",questionZh:"文章中提到能看到螢火蟲的地方變少的原因是哪一個？",options:["川岸がコンクリートで固められたこと","川の中でカワニナが増えすぎたこと","六月に雨があまり降らなくなったこと","地域の人が川に入らなくなったこと"]}]},{id:"n3-r18",title:"水に浮かぶ氷のふしぎ",titleZh:"浮在水上的冰之謎",topic:"科學",paragraphs:[{ja:"コップに水と氷を入れると、氷は沈まずに水面に浮かぶ。当たり前のように思えるが、実はこれは珍しい性質だ。多くの物質は、液体から固体になると体積が小さくなるため、固体は液体の中で沈んでしまう。ところが水は、凍ると逆に体積が約一割増えるのである。",zh:"把水和冰放進杯子裡，冰不會沉下去，而是浮在水面上。這看似理所當然，其實是很少見的性質。大多數物質從液體變成固體時體積會變小，所以固體會沉入液體中。然而，水結冰時體積反而會增加大約一成。"},{ja:"体積が増えるということは、同じ大きさで比べると、氷のほうが水より軽いということだ。だから、氷は水に浮かぶ。水が凍ると体積が増えるのは、水のつぶが規則正しく並ぶときに、つぶとつぶの間にすき間ができるからである。",zh:"體積增加，就表示以相同大小來比較的話，冰比水還要輕。所以冰會浮在水上。水結冰時體積之所以會增加，是因為水的粒子規則地排列時，粒子與粒子之間會產生空隙。"},{ja:"この性質は、私たちの生活にも関係している。たとえば、ペットボトルに水をいっぱいに入れて冷凍庫で凍らせると、ボトルがふくらんでしまう。寒い地方で、冬に水道管が破裂することがあるのも、管の中の水が凍ってふくらむためだ。",zh:"這種性質也和我們的生活有關。例如，把寶特瓶裝滿水放進冷凍庫結凍，瓶子就會脹起來。在寒冷地區，冬天有時會發生水管破裂的情形，也是因為管子裡的水結冰膨脹的緣故。"},{ja:"また、この性質は生き物の命も守っている。冬に湖が凍るとき、氷は水面に浮かんで、湖をふたのようにおおう。そのため、下の水は冷たい空気に直接触れず、底まで凍ってしまうことはめったにない。魚たちは、氷の下で春を待つことができるのだ。もし氷が水に沈んでいたら、地球の生き物の姿は今とは大きく違っていたかもしれない。",zh:"此外，這種性質也守護著生物的生命。冬天湖泊結冰時，冰會浮在水面上，像蓋子一樣覆蓋住湖面。因此，下方的水不會直接接觸冷空氣，很少會一路凍到湖底。魚兒們就能在冰層下等待春天。如果冰會沉入水中，地球上生物的樣貌或許就和現在大不相同了。"}],vocab:[{word:"沈む",reading:"しずむ",meaning:"沉、沉沒"},{word:"浮かぶ",reading:"うかぶ",meaning:"浮、漂浮"},{word:"物質",reading:"ぶっしつ",meaning:"物質"},{word:"体積",reading:"たいせき",meaning:"體積"},{word:"規則正しい",reading:"きそくただしい",meaning:"有規律的、規則的"},{word:"破裂",reading:"はれつ",meaning:"破裂"},{word:"直接",reading:"ちょくせつ",meaning:"直接"}],questions:[{question:"水が凍ると体積が増えるのはなぜか。",questionZh:"水結冰時體積為什麼會增加？",options:["水のつぶが並ぶときに、すき間ができるから","水のつぶ一つ一つが、大きくなるから","凍るときに、外から空気が入るから","冷凍庫の中で、水の量が増えるから"]},{question:"寒い地方で、冬に水道管が破裂することがあるのはなぜか。",questionZh:"在寒冷地區，冬天為什麼有時會發生水管破裂？",options:["管の中の水が凍って、ふくらむから","管の中でできた氷が、底に沈むから","冬は水道を使う人が多くなるから","冷たい空気で、管が小さくなるから"]},{question:"冬の湖について、文章の内容と合うものはどれか。",questionZh:"關於冬天的湖泊，哪一項符合文章內容？",options:["氷がふたのようになり、下の水は凍りにくい","湖の底のほうから、先に凍り始める","氷が沈むので、魚は水面の近くに集まる","冬の間、魚は湖から川へ移ってしまう"]}]},{id:"n3-r19",title:"名前のない手紙",titleZh:"沒有署名的信",topic:"推理",paragraphs:[{ja:"誕生日の朝、七時五十分に教室に入ると、机の中に白い封筒が入っていた。中のカードには横書きで「いつも話を聞いてくれてありがとう。誕生日おめでとう」とあるが、名前はどこにも書かれていない。昨日の放課後、教室の鍵を閉めたのは私で、そのとき机の中には何もなかった。",zh:"生日那天早上七點五十分，我一走進教室，就發現抽屜裡放著一個白色信封。裡面的卡片上用橫書寫著「謝謝你總是聽我說話。生日快樂」，但哪裡都沒有寫名字。昨天放學後，鎖上教室門的人是我，當時抽屜裡什麼都沒有。"},{ja:"うちの学校では、毎朝七時半に先生が教室の鍵を開ける。だから、手紙が入れられたのは、今朝の七時半から七時五十分までの間だ。私の誕生日を知っているのは、同じ班の小林さん、中村君、田中さんの三人だけである。",zh:"我們學校每天早上七點半由老師打開教室的鎖。所以，信是在今天早上七點半到七點五十分之間放進來的。知道我生日的只有同一組的小林、中村和田中三個人。"},{ja:"カードをよく見ると、どの行にも、インクがこすれたような汚れがあった。左利きの人が横書きで字を書くと、書いたばかりの字の上を手が通るので、インクがこすれやすいのだ。三人のうち、左利きなのは中村君と田中さんである。",zh:"仔細一看卡片，每一行都有像是墨水被擦過的髒污。左撇子的人橫著寫字時，手會從剛寫好的字上面經過，所以墨水很容易被擦糊。三個人之中，左撇子的是中村和田中。"},{ja:"中村君は野球部で、今朝も七時から八時十分まで、ずっとグラウンドで練習していたと、ほかの部員たちが言っていた。一方、私が教室に入ったとき、小林さんと田中さんはもう自分の席に座っていた。",zh:"中村是棒球隊的，其他隊員說，他今天早上也從七點到八點十分一直在操場練習。另一方面，我走進教室時，小林和田中已經坐在自己的座位上了。"},{ja:"左利きで、しかもその時間に教室に入れたのは、田中さんしかいない。私は田中さんの席に行って、「カード、ありがとう」と小さな声で言った。田中さんは顔を赤くして、「どうしてわかったの」と笑った。",zh:"既是左撇子、又能在那段時間進入教室的，只有田中一個人。我走到田中的座位旁，小聲地說：「謝謝你的卡片。」田中紅著臉笑著說：「你怎麼知道的？」"}],vocab:[{word:"封筒",reading:"ふうとう",meaning:"信封"},{word:"横書き",reading:"よこがき",meaning:"橫寫、橫式書寫"},{word:"鍵",reading:"かぎ",meaning:"鑰匙、鎖"},{word:"班",reading:"はん",meaning:"小組、班"},{word:"汚れ",reading:"よごれ",meaning:"髒污、污漬"},{word:"左利き",reading:"ひだりきき",meaning:"左撇子"},{word:"こすれる",reading:"こすれる",meaning:"被擦到、摩擦"}],questions:[{question:"手紙が机に入れられたのは、いつだと考えられるか。",questionZh:"可以推測信是什麼時候被放進抽屜的？",options:["今朝の七時半から七時五十分までの間","昨日の放課後、鍵を閉める前","今朝の七時から七時半までの間","今朝の八時十分よりあと"]},{question:"中村君が手紙を入れた人ではないと考えられる理由は何か。",questionZh:"可以認為中村不是放信的人，理由是什麼？",options:["その時間、ずっとグラウンドで練習していたから","中村君は右利きだから","「私」の誕生日を知らなかったから","教室の鍵を持っていなかったから"]},{question:"手紙を書いたのはだれか。また、そう考えられる理由は何か。",questionZh:"寫信的是誰？這麼認為的理由是什麼？",options:["田中さん。左利きで、その時間に教室に入れたから","小林さん。いちばん早く教室に来ていたから","中村君。三人の中で、左利きだから","小林さん。カードの字がきれいだったから"]}]},{id:"n3-r20",title:"レシートが教えてくれたこと",titleZh:"收據告訴我們的事",topic:"推理",paragraphs:[{ja:"土曜日の夕方、姉が青い顔をして帰ってきた。定期入れをなくしたらしい。中には、店での支払いにも使えるICカードの定期券と、図書館のカードが入っているという。今日は駅前のパン屋に寄ってから図書館で勉強し、最後に公園を通って歩いて帰ってきたそうだ。",zh:"星期六傍晚，姊姊臉色發青地回到家，好像是把票卡夾弄丟了。據說裡面放著也能在店裡付款的IC卡月票，以及圖書館的借書證。她今天先去了車站前的麵包店，接著在圖書館讀書，最後穿過公園走路回家。"},{ja:"「きっとパン屋で落としたんだ。お金を払うとき、定期入れを出したから」と姉は言う。たしかに、パン屋のレシートには「二時十分、ICカード払い」とある。しかし、店に電話をすると、落とし物は届いていないと言われた。",zh:"姊姊說：「一定是在麵包店弄丟的，因為付錢時我拿出了票卡夾。」的確，麵包店的收據上寫著「兩點十分，IC卡付款」。但是打電話到店裡問，對方卻說沒有人送來失物。"},{ja:"私は姉のかばんから、図書館の貸出票も見つけた。時間は三時四十分だ。「図書館でもカードを使ったよね？」と聞くと、姉は「うん。使ったあと、すぐ定期入れに戻した。それから、そのまま図書館を出たの」と答えた。",zh:"我在姊姊的包包裡又找到了圖書館的借閱單，上面的時間是三點四十分。我問：「妳在圖書館也用了卡吧？」姊姊回答：「嗯，用完馬上就放回票卡夾了。然後就直接離開圖書館了。」"},{ja:"つまり、パン屋を出たあとも、定期入れはまだ姉が持っていたのだ。図書館を出てから家に着くまでに寄ったのは、公園だけである。私がそう言うと、姉は公園のベンチでハンカチを出したことを思い出した。",zh:"也就是說，離開麵包店之後，票卡夾仍然在姊姊身上。從圖書館出來到回家之前，她只去了公園。我這麼一說，姊姊就想起自己曾在公園的長椅上拿出手帕。"},{ja:"二人で公園に行くと、入り口にある交番に、青い定期入れが届けられていた。ベンチの下に落ちていたのを、だれかが拾って届けてくれたのだ。「レシートって大事だね」と姉が言うので、私は「捨てなくてよかったね」と笑った。",zh:"我們兩人一起去公園，發現藍色的票卡夾已經被送到入口處的派出所了。原來是有人撿到掉在長椅下的票卡夾，幫忙送了過去。姊姊說：「收據真的很重要耶。」我笑著回答：「幸好沒丟掉呢。」"}],vocab:[{word:"定期入れ",reading:"ていきいれ",meaning:"票卡夾、月票夾"},{word:"支払い",reading:"しはらい",meaning:"付款、支付"},{word:"寄る",reading:"よる",meaning:"順路去、順便到"},{word:"落とし物",reading:"おとしもの",meaning:"失物、遺失物"},{word:"貸出票",reading:"かしだしひょう",meaning:"借閱單"},{word:"交番",reading:"こうばん",meaning:"派出所"},{word:"拾う",reading:"ひろう",meaning:"撿、拾"}],questions:[{question:"姉が最初に、定期入れを落とした場所だと思ったのはどこか。",questionZh:"姊姊一開始認為票卡夾是在哪裡弄丟的？",options:["パン屋","図書館","公園","駅"]},{question:"パン屋で落としたのではないとわかったのはなぜか。",questionZh:"為什麼能知道不是在麵包店弄丟的？",options:["パン屋のあと、図書館でもカードを使っていたから","パン屋では、現金でお金を払っていたから","パン屋の店員が、姉が帰るところを見ていたから","その日、姉はパン屋に寄っていなかったから"]},{question:"定期入れはどこで見つかったか。",questionZh:"票卡夾是在哪裡找到的？",options:["公園の入り口にある交番","パン屋のレジの横","図書館のカウンター","姉のかばんの中"]}]}]},1247,[]);
